    def open_exfiltration_window(self):      
        self.token_var.set("")
        self.folder_var.set("")    
        if self.window_exfiltration and self.window_exfiltration.winfo_exists():
            self.window_exfiltration.deiconify()
            self.window_exfiltration.lift()
            return
        self.window_exfiltration = tk.Toplevel(self.window_listener)
        self.window_exfiltration.title("Exfiltration Profile")
        self.window_exfiltration.resizable(False, False)
        self.window_exfiltration.withdraw()
        self.center_window(self.window_exfiltration, 400, 200)
        self.window_exfiltration.deiconify()
        self.window_exfiltration.transient(self.window_listener)
