    def create_menu(self):
            fram = tk.Frame(self.main_application_window, height=40, relief=tk.RIDGE, bd=1)
            fram.pack(fill=tk.X)
            fram.pack_propagate(False)
            self.current_dropdown = None
            self.current_dropdown_owner = None
            self.current_submenu = None
            def close_dropdown():
                if self.current_submenu and self.current_submenu.winfo_exists():
                    self.current_submenu.destroy()
                    self.current_submenu = None
                if self.current_dropdown and self.current_dropdown.winfo_exists():
                    self.current_dropdown.destroy()
                    self.current_dropdown = None
                    self.current_dropdown_owner = None
                self.main_application_window.unbind("<Button-1>")
            def bind_outside_click():
                def on_outside_click(event):
                    if self.current_dropdown and self.current_dropdown.winfo_exists():
                        x, y = event.x_root, event.y_root
                        drop_x1 = self.current_dropdown.winfo_rootx()
                        drop_y1 = self.current_dropdown.winfo_rooty()
                        drop_x2 = drop_x1 + self.current_dropdown.winfo_width()
                        drop_y2 = drop_y1 + self.current_dropdown.winfo_height()
                        if not (drop_x1 <= x <= drop_x2 and drop_y1 <= y <= drop_y2):
                            close_dropdown()
                self.main_application_window.bind("<Button-1>", on_outside_click, add="+")
            def create_item(parent, icon, text, dropdown_options=None, command=None, extra_width=90):
                default_bg = parent.cget("bg")
                frame = tk.Frame(parent, bg=default_bg)
                frame.pack(side=tk.LEFT, fill=tk.Y, padx=(0, 1))
                icon_label = tk.Label(frame, image=icon, bg=default_bg)
                icon_label.pack(side=tk.LEFT, pady=0, padx=(5,0))
                text_label = tk.Label(frame, text=text, bg=default_bg)
                text_label.pack(side=tk.LEFT, pady=0, padx=3)
                def on_enter(e):
                    frame.config(bg="#730f06")
                    icon_label.config(bg="#730f06")
                    text_label.config(bg="#730f06")
                    if dropdown_options:
                        if self.current_dropdown_owner == frame and self.current_dropdown and self.current_dropdown.winfo_exists():
                            return
                        close_dropdown()
                        create_dropdown(frame, dropdown_options, extra_width)
                    else:
                        close_dropdown()
                def on_leave(e):
                    frame.config(bg=default_bg)
                    icon_label.config(bg=default_bg)
                    text_label.config(bg=default_bg)
                frame.bind("<Enter>", on_enter)
                frame.bind("<Leave>", on_leave)
                icon_label.bind("<Enter>", on_enter)
                icon_label.bind("<Leave>", on_leave)
                text_label.bind("<Enter>", on_enter)
                text_label.bind("<Leave>", on_leave)
                if command:
                    def execute_command():
                        close_dropdown()
                        self.main_application_window.after(50, command)
                    frame.bind("<Button-1>", lambda e: execute_command())
                    icon_label.bind("<Button-1>", lambda e: execute_command())
                    text_label.bind("<Button-1>", lambda e: execute_command())
                return frame
            def create_dropdown(parent_frame, options, extra_width=90, parent_dropdown=None):
                dropdown = tk.Frame(self.main_application_window, bg="#383636", bd=1, relief=tk.RIDGE)
                if parent_dropdown is None:
                    self.current_dropdown = dropdown
                    self.current_dropdown_owner = parent_frame
                width = parent_frame.winfo_width() + extra_width
                if parent_dropdown:
                    x = parent_dropdown.winfo_rootx() - self.main_application_window.winfo_rootx() + parent_dropdown.winfo_width()
                    y = parent_frame.winfo_rooty() - self.main_application_window.winfo_rooty()
                else:
                    x = parent_frame.winfo_rootx() - self.main_application_window.winfo_rootx()
                    y = parent_frame.winfo_rooty() - self.main_application_window.winfo_rooty() + parent_frame.winfo_height()
                dropdown.place(x=x, y=y, width=width)
                for i, option in enumerate(options):
                    if len(option) == 3:
                        label_text, cmd, item_icon = option
                    else:
                        label_text, cmd = option
                        item_icon = None
                    row = tk.Frame(dropdown, bg="#383636")
                    row.pack(fill=tk.X)
                    widgets_in_row = [row]
                    if item_icon is not None:
                        icon_lbl = tk.Label(row, image=item_icon, bg="#383636")
                        icon_lbl.image = item_icon  
                        icon_lbl.pack(side=tk.LEFT, padx=(5, 3), pady=2)
                        widgets_in_row.append(icon_lbl)
                    lbl = tk.Label(row, text=label_text, bg="#383636", fg="white", anchor="w", padx=5)
                    lbl.pack(side=tk.LEFT, fill=tk.X, expand=True)
                    widgets_in_row.append(lbl)
                    for w in widgets_in_row:
                        w.bind("<Enter>", lambda e, ws=widgets_in_row: [x.config(bg="#730f06") for x in ws])
                        w.bind("<Leave>", lambda e, ws=widgets_in_row: [x.config(bg="#383636") for x in ws])
                    if isinstance(cmd, list):
                        def open_submenu(e, submenu_options=cmd, parent_row=row):
                            if self.current_submenu and self.current_submenu.winfo_exists():
                                self.current_submenu.destroy()
                            submenu = create_dropdown(parent_row, submenu_options, extra_width=50, parent_dropdown=dropdown)
                            self.current_submenu = submenu
                        for w in widgets_in_row:
                            w.bind("<Enter>", open_submenu, add="+")
                    else:
                        def make_command_handler(command_func):
                            def handler(e):
                                if self.current_submenu and self.current_submenu.winfo_exists():
                                    self.current_submenu.destroy()
                                    self.current_submenu = None
                                close_dropdown()
                                self.main_application_window.after(50, command_func)
                            return handler
                        handler = make_command_handler(cmd)
                        for w in widgets_in_row:
                            w.bind("<Button-1>", handler)
                        def check_mouse_outside():
                            if not dropdown.winfo_exists():
                                return
                            x = self.main_application_window.winfo_pointerx()
                            y = self.main_application_window.winfo_pointery()
                            dx1 = dropdown.winfo_rootx()
                            dy1 = dropdown.winfo_rooty()
                            dx2 = dx1 + dropdown.winfo_width()
                            dy2 = dy1 + dropdown.winfo_height()
                            inside_dropdown = dx1 <= x <= dx2 and dy1 <= y <= dy2
                            px1 = parent_frame.winfo_rootx()
                            py1 = parent_frame.winfo_rooty()
                            px2 = px1 + parent_frame.winfo_width()
                            py2 = py1 + parent_frame.winfo_height()
                            inside_parent = px1 <= x <= px2 and py1 <= y <= py2
                            inside_submenu = False
                            if self.current_submenu and self.current_submenu.winfo_exists():
                                sx1 = self.current_submenu.winfo_rootx()
                                sy1 = self.current_submenu.winfo_rooty()
                                sx2 = sx1 + self.current_submenu.winfo_width()
                                sy2 = sy1 + self.current_submenu.winfo_height()
                                inside_submenu = sx1 <= x <= sx2 and sy1 <= y <= sy2
                            if not (inside_dropdown or inside_parent or inside_submenu):
                                close_dropdown()
                            else:
                                dropdown.after(100, check_mouse_outside)
                        dropdown.after(100, check_mouse_outside)
                    if i < len(options) - 1:
                        sep = tk.Frame(dropdown, height=1, bg="#555555")
                        sep.pack(fill=tk.X, padx=2, pady=2)
                bind_outside_click()
                return dropdown
            create_item(fram, self.server_icon, "Reaper Node", command=self.open_listener_window)
            create_item(fram, self.telegram_bot_icon, "Telegram Bot", command=self.show_window_telegram)
            create_item(fram, self.discord_bot_icon, "Discord Channel", command=self.show_window_discord)
            create_item(fram, self.microsoft_team_bot_icon, "Microsoft Teams", command=self.open_teams_agent)
            create_item(fram, self.arsenal_icon, "Script Obfuscator",command=self.open_script_obfuscator_window)
            create_item(fram, self.spear_phasing_icon, "Spear Phishing", command=self.open_phishing_window)
            create_item(fram, self.host_file_icon, "Host File", command=self.open_host_file_window)
