    def select_encryption(self, encryption_type):
        if self.selected_encryption_type == encryption_type:
            return
        self.selected_encryption_type = encryption_type
        inactive_fg = '#515151'
        active_fg = 'white'
        active_bg = '#3E3E3E'
        inactive_bg = '#2F2F2F'
        readonly_fg = '#959595'
        texts = {"AES": self.aes_label_text,"XOR": self.xor_label_text,"RC4": self.rc4_label_text,"RSA": self.rsa_label_text,"DES": self.des_label_text,"CHACHA": self.chacha_label_text,"Without Encryption": self.no_encryption_label}
        labels = {"AES": self.aes_radio,"XOR": self.xor_radio,"RC4": self.rc4_radio,"RSA": self.rsa_radio,"DES": self.des_radio,"CHACHA": self.chacha_radio,"Without Encryption": self.no_encryption_radio}
        entries = {"AES": self.aes_base64_entry,"XOR": self.xor_key_entry,"RC4": self.rc4_key_entry,"DES": self.des_key_entry,"CHACHA": self.chacha_key_entry}
        for t in texts.values():
            t.config(fg=inactive_fg)
        for l in labels.values():
            l.config(image=self.radio_unselected_icon)
        for e in entries.values():
            e.config(state="readonly", readonlybackground=inactive_bg, fg=readonly_fg, bg=inactive_bg)
        texts[encryption_type].config(fg=active_fg)
        labels[encryption_type].config(image=self.radio_selected_icon)
        if encryption_type in entries:
            entry = entries[encryption_type]
            entry.config(state="normal", fg=active_fg, bg=active_bg)
            entry.focus_force()
    def browse_button(self,event):
        self.select_encryption("RSA")
        self.load_key_file()
    def CustomEntry(self,parent, limit, **kwargs):
        def on_validate(P):
            return len(P) <= limit
        vcmd = parent.register(on_validate)
        entry = tk.Entry(
            parent,
            validate="key",
            validatecommand=(vcmd, "%P"),
            **kwargs
        )
        return entry
