        def block_column_resize(event):
            region = self.proxy_table_proxy.identify_region(event.x, event.y)
            if region == "separator":  
                return "break"
        self.proxy_table_proxy.bind("<Button-1>", block_column_resize)
        def copy_first_row(event=None):
            animate_click()
            items = self.session_authentication_table.get_children()
            if not items:
                return
            first_item = items[0]
            values = self.session_authentication_table.item(first_item, "values")
            if values:
                text = str(values[0])
                pyperclip.copy(text)
        self.copy_to_clipboard_label.bind("<Button-1>", copy_first_row)        
        def animate_click():
            normal_photo = self.copy_icon  
            img = Image.open(resource_path("Stagers-Loaders/image/copy_icon.png"))
            img_resized = img.resize((23, 23))
            self.copy_icon_small = ImageTk.PhotoImage(img_resized)
            self.copy_to_clipboard_label.config(image=self.copy_icon_small)
            def reset():
                self.copy_to_clipboard_label.config(image=normal_photo)
            self.copy_to_clipboard_label.after(100, reset)
        tk.Button(self.button_frame_left,width=12, text="Start Server",activebackground="#9A1105", bg='#730f06', fg='white', command=self.check_key_validity).pack(side=tk.LEFT,padx=(20,0))
