        tk.Button(self.button_frame_left,width=12, text="Start Proxy", activebackground="#9A1105", bg='#730f06', fg='white', command=self.start_proxy_server_proxy).pack(side=tk.RIGHT,padx=(15,0))
        self.window_listener.deiconify()
        self.window_listener.lift()
