    def show_session_context_menu(self, event):
        row_id = self.session_table.identify_row(event.y)
        if row_id:
            self.session_table.selection_set(row_id)
            self.update_terminal_options(event)
            selected_item = self.session_table.selection()[0] if self.session_table.selection() else None
            if not selected_item:
                return
            row_values = self.session_table.item(selected_item, "values")
            if len(row_values) < 6:
                return
            session_id = row_values[0] if len(row_values) > 0 else ""
            system_name = self.session_table.item(selected_item, "text").lower()
            menu_window = tk.Toplevel(self.session_table.winfo_toplevel())
            menu_window.withdraw()
            menu_window.wm_overrideredirect(True)
            menu_window.configure(bg='#212121')
            self.current_menu_window = menu_window
            border_frame = tk.Frame(menu_window, bg='#9A1105', padx=1, pady=1)
            border_frame.pack()
            inner_frame = tk.Frame(border_frame, bg='#212121')
            inner_frame.pack(fill='both', expand=True)
            def hide_menu():
                try:
                    menu_window.destroy()
                    self.current_menu_window = None
                except:
                    pass
            def file_browse_action():
                hide_menu()
                self.send_file_browse()
            def exfiltration_action():
                hide_menu()
                self.exfiltration_script()
            def toggle_address_action():
                hide_menu()
                self.toggle_address_state()
            def disconnect_action():
                hide_menu()
                self.disconnect_selected_session()
            def remove_action():
                hide_menu()
                self.remove_selected_session()
            def defenders_action():
                hide_menu()
                self.enumeration_script()
            def screenshot_action():
                hide_menu()
                self.take_screenshot()
            def black_carbon_action():
                hide_menu()
                self.black_carbon_script()
            def create_menu_item(parent, text, icon, command):
                frame = tk.Frame(parent, bg='#212121')
                frame.pack(fill='x')
                if icon:
                    icon_label = tk.Label(
                        frame,
                        image=icon,
                        bg='#212121',
                        cursor='hand2'
                    )
                    icon_label.pack(side='left', padx=(10, 5), pady=8)
                text_label = tk.Label(
                    frame,
                    text=text,
                    bg='#212121',
                    fg='white',
                    cursor='hand2',
                    font=('Arial', 10)
                )
                text_label.pack(side='left', padx=(0, 20), pady=8, fill='x', expand=True)
                def on_enter(e):
                    frame.configure(bg='#9A1105')
                    if icon:
                        icon_label.configure(bg='#9A1105')
                    text_label.configure(bg='#9A1105')
                def on_leave(e):
                    frame.configure(bg='#212121')
                    if icon:
                        icon_label.configure(bg='#212121')
                    text_label.configure(bg='#212121')
                def on_click(e):
                    command()
                    hide_menu()
                widgets_to_bind = [frame, text_label]
                if icon:
                    widgets_to_bind.append(icon_label)
                for widget in widgets_to_bind:
                    widget.bind('<Enter>', on_enter)
                    widget.bind('<Leave>', on_leave)
                    widget.bind('<Button-1>', on_click)
                return frame
            menu_items = []
            if "linux" in system_name.lower():
                menu_items.append(("File Browse", self.file_browse_icon, file_browse_action))
                hidden = self.hidden_addresses.get(session_id, False)
                if hidden:
                    menu_items.append(("Show Address", self.show_address_icon, toggle_address_action))
                else:
                    menu_items.append(("Hide Address", self.hide_address_icon, toggle_address_action))
                menu_items.append(("Disconnect Beacon", self.disconnect_icon, disconnect_action))
                menu_items.append(("Remove Beacon", self.remove_icon, remove_action))
            else:
                menu_items.append(("Defenders Enum", self.defenders_icon, defenders_action))
                menu_items.append(("File Browse", self.file_browse_icon, file_browse_action))
                menu_items.append(("Screenshot", self.screenshot_icon, screenshot_action))
                if getattr(self, 'show_exfiltration', False):
                    menu_items.append(("Data Exfiltration", self.exfiltration_icon, exfiltration_action))
                menu_items.append(("Black Carbon", self.black_carbon_icon, black_carbon_action))
                hidden = self.hidden_addresses.get(session_id, False)
                if hidden:
                    menu_items.append(("Show Address", self.show_address_icon, toggle_address_action))
                else:
                    menu_items.append(("Hide Address", self.hide_address_icon, toggle_address_action))
                menu_items.append(("Disconnect Beacon", self.disconnect_icon, disconnect_action))
                menu_items.append(("Remove Beacon", self.remove_icon, remove_action))
            for text, icon, command in menu_items:
                create_menu_item(inner_frame, text, icon, command)
            menu_window.update_idletasks()
            width = menu_window.winfo_reqwidth()
            height = menu_window.winfo_reqheight()
            x = event.x_root
            y = event.y_root
            screen_width = menu_window.winfo_screenwidth()
            screen_height = menu_window.winfo_screenheight()
            if x + width > screen_width:
                x = screen_width - width - 10
            if y + height > screen_height:
                y = screen_height - height - 10
            menu_window.geometry(f"{width}x{height}+{x}+{y}")
            menu_window.deiconify()
            menu_window.lift()
            menu_window.focus_set()
            menu_window.transient(self.session_table.winfo_toplevel())
            menu_window.bind("<FocusOut>", lambda e: hide_menu())
            menu_window.bind("<Escape>", lambda e: hide_menu())
