    def open_listener_management_window(self):
        if self.Session_Manager and self.Session_Manager.winfo_exists():
            self.Session_Manager.deiconify()
            self.Session_Manager.lift()
            return
        self.Session_Manager = tk.Toplevel(self.main_application_window)
        self.Session_Manager.title("Listeners Table")
        self.Session_Manager.resizable(False, False)
        self.Session_Manager.withdraw()
        self.center_window(self.Session_Manager, 1000, 450)
        self.Session_Manager.deiconify()
        self.Session_Manager.transient(root)
        self.Session_Manager.lift()
        def remove_selected_listener():
            selected = self.session_table_listener.selection()
            if not selected:
                messagebox.showwarning("No Selection", "Please select a listener to remove.", parent=self.Session_Manager)
                return
            confirm = messagebox.askyesno("Confirm Delete", "Are you sure you want to delete the selected listener?", parent=self.Session_Manager)
            if not confirm:
                return
            for item in selected:
                try:
                    item_values = self.session_table_listener.item(item, "values")
                    listener_name = item_values[0] 
                    self.session_table_listener.delete(item)
                    if hasattr(self, "saved_sessions"):
                        self.saved_sessions = [
                            row for row in self.saved_sessions if row[0] != listener_name
                        ]
                    if hasattr(self, "listener_names") and listener_name in self.listener_names:
                        self.listener_names.remove(listener_name)
                    self.update_output_text(f"[+] Removed listener: {listener_name}\n\n", is_general=True)
                except Exception as e:
                    messagebox.showerror("Error", f"Failed to remove listener:\n{str(e)}", parent=self.Session_Manager)
        columns = ("Listener Name", "Listener Address", "Network Protocol", "Encryption","Exfiltration Profile", "Status")
        self.session_table_listener = ttk.Treeview(self.Session_Manager, columns=columns, show="headings", style="listener.Treeview")
        for col in columns:
            self.session_table_listener.heading(col, text=col)
            self.session_table_listener.column(col, width=110, anchor="center")
        scrollbar = ctk.CTkScrollbar(self.session_table_listener, command=self.session_table_listener.yview,bg_color="#1D1D1D",cursor="hand2")
        scrollbar.pack(side="right", fill="y", pady=(25, 3),padx=2)
        self.session_table_listener.configure(yscrollcommand=scrollbar.set)
        self.session_table_listener.pack(expand=True, fill=tk.BOTH, pady=0)
        self.session_table_menu_listener = tk.Menu(self.main_application_window, tearoff=0,bg='#212121', activebackground="#9A1105", relief="ridge")
        self.session_table_listener.bind("<Button-3>", self.show_session_context_menu_listener)
        if hasattr(self, "saved_sessions"):
            for row in self.saved_sessions:
                self.session_table_listener.insert("", "end", values=row)
        button_frame = tk.Frame(self.Session_Manager)
        button_frame.pack(pady=10)
        tk.Button(button_frame, text="Add Listener", bg="#730f06", fg="#FFFFFF",activebackground="#9A1105", activeforeground="#FFFFFF", width=15,command=self.open_listener_window).pack(side=tk.LEFT, padx=10)
        tk.Button(button_frame, text="Stop Listener", bg="#730f06", fg="#FFFFFF",activebackground="#9A1105", activeforeground="#FFFFFF", width=15,command=self.stop_listener).pack(side=tk.LEFT, padx=10)
        tk.Button(button_frame, text="Remove Listener", bg="#730f06", fg="#FFFFFF",activebackground="#9A1105", activeforeground="#FFFFFF", width=15,command=remove_selected_listener).pack(side=tk.LEFT, padx=10)
    def stop_listener(self):
        selected = self.session_table_listener.selection()
        if not selected:
            messagebox.showwarning("Warning", "Please select a listener to stop.", parent=self.Session_Manager)
            return
        confirm = messagebox.askyesno("Confirm Stop", "Are you sure you want to stop the selected listener ?", parent=self.Session_Manager)
        if not confirm:
            return
        for item in selected:
            values = self.session_table_listener.item(item, "values")
            listener_name = values[0]
            listener_address = values[1]  
            protocol = values[2]
            if protocol == "MTProto 2.0":
                found_uuid = None
                found_server = None
                for uuid_key, server in getattr(self, "running_server_instances", {}).items():
                    if isinstance(uuid_key, str) and hasattr(server, 'session_id') and listener_name in getattr(server, 'session_id', ''):
                        found_uuid = uuid_key
                        found_server = server
                        break
                if not found_uuid:
                    for uuid_key, server in getattr(self, "running_server_instances", {}).items():
                        if isinstance(uuid_key, str) and getattr(server, 'phone_number', None):
                            for session in getattr(self, "saved_sessions", []):
                                if session[0] == listener_name and len(session) > 8 and session[8] == server.phone_number:
                                    found_uuid = uuid_key
                                    found_server = server
                                    break
                            if found_uuid:
                                break
                if found_uuid and found_uuid in self.running_server_instances:
                    server = self.running_server_instances[found_uuid]
                    if hasattr(server, 'is_running') and server.is_running:
                        if hasattr(server, 'disconnect_telegram_agent'):
                            server.disconnect_telegram_agent()
                        elif hasattr(server, 'on_closing'):
                            server.on_closing()
                    elif hasattr(server, 'client') and hasattr(server, 'loop'):
                        try:
                            import asyncio
                            async def force_disconnect():
                                if server.client:
                                    await server.client.disconnect()
                            if server.loop and server.loop.is_running():
                                asyncio.run_coroutine_threadsafe(force_disconnect(), server.loop)
                        except:
                            pass
                    del self.running_server_instances[found_uuid]
                if hasattr(self, 'telegram_agents') and found_server:
                    if found_server in self.telegram_agents:
                        self.telegram_agents.remove(found_server)
                self.api_id = None
                self.api_hash = None
                self.phone_number = None
                self.your_username = None
                if hasattr(self, 'session_manager') and hasattr(self.session_manager, 'active_phones'):
                    phone_to_remove = found_server.phone_number if found_server and hasattr(found_server, 'phone_number') else None
                    if phone_to_remove and phone_to_remove in self.session_manager.active_phones:
                        self.session_manager.active_phones.discard(phone_to_remove)
                self.update_output_text(
                    f"[+] Stopped Telegram Bot listener and cleared all data (Listener Name: {listener_name})\n\n",
                    is_general=True
                )
                values = list(values)
                values[5] = "Stopped"
                self.session_table_listener.item(item, values=values)
                if hasattr(self, "saved_sessions"):
                    self.saved_sessions = [
                        values if session[0] == listener_name else session
                        for session in self.saved_sessions
                    ]
                continue
            if protocol == "Gateway API":
                found_server = None
                if hasattr(self, 'discord_agents'):
                    for agent in self.discord_agents:
                        if hasattr(agent, 'listener_name') and agent.listener_name == listener_name:
                            found_server = agent
                            break
                        if hasattr(agent, 'session_id') and listener_name in agent.session_id:
                            found_server = agent
                            break
                if not found_server:
                    for uuid_key, server in getattr(self, "running_server_instances", {}).items():
                        if hasattr(server, 'listener_name') and server.listener_name == listener_name:
                            found_server = server
                            break
                if found_server:
                    if hasattr(found_server, 'disconnect_discord_agent'):
                        found_server.disconnect_discord_agent()
                    elif hasattr(found_server, 'on_closing'):
                        found_server.on_closing()
                    if hasattr(self, 'discord_agents') and found_server in self.discord_agents:
                        self.discord_agents.remove(found_server)
                    for uuid_key, server in list(getattr(self, "running_server_instances", {}).items()):
                        if server == found_server:
                            del self.running_server_instances[uuid_key]
                            break
                    if hasattr(self, 'session_manager_discord') and hasattr(found_server, 'bot_token'):
                        self.session_manager_discord.remove_bot(found_server.bot_token)
                    self.update_output_text(
                        f"[+] Stopped Discord Channel listener (Listener Name: {listener_name})\n\n",
                        is_general=True
                    )
                else:
                    self.update_output_text(f"[-] No active Discord channel found for {listener_name}\n", is_general=True)
                values = list(values)
                values[5] = "Stopped"
                self.session_table_listener.item(item, values=values)
                if hasattr(self, "saved_sessions"):
                    self.saved_sessions = [
                        session for session in self.saved_sessions
                        if session[0] != listener_name
                    ]
                continue
            try:
                ip, port = listener_address.split(":")
                ip = ip.strip()
                port = int(port.strip())
            except:
                self.update_output_text(f"[-] Invalid listener address format: {listener_address}\n", is_general=True)
                continue
            key = (ip, port)
            if hasattr(self, "running_server_instances") and key in self.running_server_instances:
                server = self.running_server_instances[key]
                server.stop_server()
                self.update_output_text(
                    f"[+] Stopped listener on {ip}:{port} (Listener Name: {listener_name} - Protocol: {protocol})\n\n",
                    is_general=True
                )
                del self.running_server_instances[key]
            else:
                self.update_output_text(f"\n[-] No active server found for {ip}:{port}\n", is_general=True)
            values = list(values)
            values[5] = "Stopped"
            self.session_table_listener.item(item, values=values)
            if hasattr(self, "saved_sessions"):
                self.saved_sessions = [
                    values if session[0] == listener_name else session
                    for session in self.saved_sessions
                ]
