        if enabled:
            self.DGA_Timer_entry.config(bg="#3E3E3E",fg="#FFFFFF",state="normal",selectbackground="#730f06",selectforeground="#FFFFFF",insertbackground="#730f06",highlightcolor="#FFFFFF")
            self.DGA_Timer_label.config(fg="#FFFFFF")
