    def get_entries_and_labels(self):
        entries = (self.max_txt_size_entry,self.dga_domains_entry,self.public_resolver_entry,self.spoofed_txt_record_entry,self.pivot_domain_entry,self.shadow_domain_entry,)
        labels = (self.label_maxdns,self.label_rotational_dga,self.label_public_doh_server,self.label_spoofed_txt_record,self.label_pivot_a_record,self.label_shadow_a_record,)
        return entries, labels
    def on_protocol_change(self, *args):
        protocol = self.selected_protocol_type.get()
        entries, labels = self.get_entries_and_labels()
        if protocol in ["Reverse TCP", "HTTP"]:  
            self.ja3s_fingerprinting_enable.set(False)
            self.label_ja3s.configure(fg="#515151")  
        if protocol in ["QUIC","DOH","HTTPS"]:  
            self.ja3s_fingerprinting_enable.set(True)
            self.label_ja3s.configure(fg="#FFFFFF")  
        if protocol in ("QUIC", "Reverse TCP"):
            self.disable_protocol_inputs()
            self.set_dga_timer("0", enabled=False)
            self.disable_entries_with_labels(entries, labels)
        elif protocol == "DOH":
            self.enable_protocol_inputs()
            self.set_dga_timer("5", enabled=True)
            self.set_dga_timer("5", enabled=True)
            self.enable_entries_with_labels(entries, labels)
            self.bind_numbers_only_entry(self.max_txt_size_entry)
        elif protocol in ("HTTP", "HTTPS"):
            self.enable_protocol_inputs()
            self.set_dga_timer("0", enabled=False)
            self.disable_entries_with_labels(entries, labels)
    def is_port_in_use(self,ip, port):
        try:
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as tcp_sock:
                tcp_sock.bind((ip, port))
        except OSError:
            return True
        try:
            with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as udp_sock:
                udp_sock.bind((ip, port))
        except OSError:
            return True
        return False
    def validate_ip_port(self, ip_str, port_str, parent=None):
        try:
            ipaddress.ip_address(ip_str)
        except ValueError:
            messagebox.showerror("Input Error", "Invalid IP address", parent=parent)
            return None, None
        try:
            port = int(port_str)
            if not (1 <= port <= 65535):
                raise ValueError
        except ValueError:
            messagebox.showerror("Input Error", "Port must be between 1 and 65535", parent=parent)
            return None, None
        if self.is_port_in_use(ip_str, port):
            messagebox.showerror("Input Error", "Port is already in use", parent=parent)
            return None, None
        return ip_str, port
    def check_key_validity(self):
        protocol = self.selected_protocol_type.get()
        encryption_type = self.selected_encryption_type
        key = self.aes_base64_entry.get()
        uris_text = self.uris_entry.get("1.0", tk.END).strip()
        value = self.jitter_start_entry.get().strip()
        listener_name = ""
        if hasattr(self, 'listener_name_entry') and self.listener_name_entry:
            listener_name = self.listener_name_entry.get().strip()
        self.http_servers = {}
        if not listener_name:
            messagebox.showerror("Error", "Listener name cannot be empty", parent=self.window_listener)
            return
        ip, port = self.validate_ip_port(self.listener_ip_entry.get(), self.listener_port_entry.get(), self.window_listener)
        if ip is None:
            return
        fields = [
            ("Sleep (in milliseconds)", self.sleep_entry),
            ("Reconnect Timeout (in minutes)", self.reconnect_timeout_entry),
            ("Reconnect Delay (in seconds)", self.reconnect_delay_entry),
            ("Jitter (in seconds) - From", self.jitter_start_entry),
            ("Jitter (in seconds) - To", self.jitter_end_entry),
        ]
        for label, entry in fields:
            if not entry.get().strip():
                messagebox.showerror("Missing Value", f"Please enter a value for: {label}", parent=self.window_listener)
                return
        if not uris_text:
            messagebox.showerror("Warning", "URIs field cannot be empty", parent=self.window_listener)
            return
        if listener_name in self.listener_names:
            messagebox.showerror("Error", "This name is already used", parent=self.window_listener)
            return
        try:
            start_jitter = float(self.jitter_start_entry.get())
            end_jitter = float(self.jitter_end_entry.get())
            sleep = float(self.sleep_entry.get()) / 1000
            reconnect_delay = float(self.reconnect_delay_entry.get())
            reconnect_value = int(self.reconnect_delay_entry.get())
            timeout_value = int(self.jitter_end_entry.get())
        except ValueError:
            messagebox.showerror("Input Error", "Numeric fields must contain valid numbers", parent=self.window_listener)
            return
        if protocol == "DOH":
            if sleep < 5.0:
                messagebox.showerror("Error", f"Sleep must be at least 5000 milliseconds", parent=self.window_listener)
                return
        if end_jitter < start_jitter:
            messagebox.showerror("Error", "End Jitter must be >= Start Jitter", parent=self.window_listener)
            return
        if (start_jitter + end_jitter + sleep) > reconnect_delay:
            messagebox.showerror("Error","Sleep + Start Jitter + End Jitter must be <= Reconnect Threshold",parent=self.window_listener)
            return
        if reconnect_value < timeout_value:
            messagebox.showwarning("Warning",f"Reconnect Delay ({reconnect_value}) must be >= Jitter ({timeout_value})",parent=self.window_listener)
            return
        if not value:
            messagebox.showerror("Error", "Value cannot be empty.", parent=self.window_listener)
            return
        if encryption_type == "AES":
            if len(key) not in [16, 24, 32]:
                messagebox.showerror("Invalid Key", "AES key must be 16, 24, or 32 bytes long", parent=self.window_listener)
                return
        elif encryption_type == "XOR":
            try:
                self.xor_encryption_key = int(self.xor_key_entry.get(), 0)
                if not (1 <= self.xor_encryption_key <= 255):
                    raise ValueError
            except ValueError:
                messagebox.showerror("Input Error", "XOR key must be between 1 and 255", parent=self.window_listener)
                return
        elif encryption_type == "RC4":
            try:
                value = self.rc4_key_entry.get().strip()
                rc4_key = int(value, 0)
                if not (1 <= rc4_key <= 255):
                    raise ValueError
                self.rc4_key = rc4_key
            except Exception:
                messagebox.showerror("Input Error", "Invalid RC4 key", parent=self.window_listener)
                return
        elif encryption_type == "DES":
            des_key = self.des_key_entry.get().encode() if hasattr(self, "des_key_entry") else None
            if not des_key or len(des_key) != 8:
                messagebox.showerror("Invalid Key", "DES key must be exactly 8 bytes", parent=self.window_listener)
                return
        elif encryption_type == "CHACHA":
            chacha_key = self.chacha_key_entry.get().encode()
            if len(chacha_key) != 32:
                messagebox.showerror("Invalid Key", "ChaCha key must be 32 bytes", parent=self.window_listener)
                return
        elif encryption_type == "RSA":
            if not hasattr(self, "rsa_key"):
                messagebox.showerror("Missing Key", "Load RSA private key first", parent=self.window_listener)
                return
        elif encryption_type == "Encryption_other":
            messagebox.showerror("Warning", "No encryption selected", parent=self.window_listener)
            return
        self.start_server()
        self.listener_names.append(listener_name)
