        sess = self.doh_xor_listener_instance.sessions[session_id]
        encrypted_command = xor_encrypt_decrypt_string(command.strip(), self.xor_encryption_key,encoding_type)
        checksum = hashlib.sha256(command.encode('utf-8')).hexdigest()[:8]
        max_payload = 190
        prefix_template = "cb:{part}/{total}:{checksum}:"
        example_prefix = prefix_template.format(part=999, total=999, checksum="12345678")
        prefix_overhead = len(example_prefix)
        chunk_size = max_payload - prefix_overhead
        if chunk_size < 20:
            chunk_size = 20
        chunks = []
        i = 0
        while i < len(encrypted_command):
            chunks.append(encrypted_command[i:i + chunk_size])
            i += chunk_size
        total = len(chunks)
        pending_parts = []
        for part_num, chunk in enumerate(chunks, 1):
            prefix = prefix_template.format(part=part_num, total=total, checksum=checksum)
            record_text = f"{prefix}{chunk}"
            pending_parts.append(record_text)
        sess["pending_command_parts"] = pending_parts
        sess["sent_parts_count"]     = 0
        sess["command_checksum"]     = checksum
        sess["command_total_parts"]  = total
        sess["command"]              = ""  
        return True   
