    def update_terminal_options_for_session(self, mode):
        self.dropdown_menu.delete(0, "end")
        selected_item = self.session_table.selection()
        if selected_item:
            system_name = self.session_table.item(selected_item[0], "text").lower()
            if "linux" in system_name.lower():
                new_values = ["Bash"]
                self.arrow_button_terminal.pack_forget()
                self.button_terminal_options.pack_forget()
            else:
                new_values = ["PowerShell", "CMD"]
                if not self.arrow_button_terminal.winfo_ismapped():
                    self.arrow_button_terminal.pack(side=tk.RIGHT, fill=tk.Y)
                if not self.button_terminal_options.winfo_ismapped():
                    self.button_terminal_options.pack(side=tk.RIGHT)
            for option in new_values:
                self.dropdown_menu.add_command(label=option,command=lambda v=option: self.select_option(v))
            if mode in new_values:
                self.selected_var.set(mode)
            else:
                self.selected_var.set(new_values[0])            
    def on_session_select(self, event=None):
        selected_item = self.session_table.selection()
        if selected_item:
            session_id = self.session_table.item(selected_item, 'values')[0]
            if getattr(self, 'current_view', None) == 'session' and getattr(self, 'current_session_id', None) == session_id:
                return
            self.current_view = 'session'
            self.current_session_id = session_id
            file_path = os.path.join("Logs - Cert", "Beacons", f"{session_id}.log")
            self.update_terminal_options(event)
            self.output_text.delete('1.0', tk.END)
            self.output_text.insert(tk.END, "\n\n\n\n")
            self.general_logo_label.pack_forget()  
            if os.path.exists(file_path):
                with open(file_path, "r", encoding="utf-8") as file:
                    content = file.read()
                    if "---CLEAR---" in content:
                        content = content.split("---CLEAR---")[-1]
                    if any(marker in content for marker in ["A9F2KX", "R7M4PV", "3ZQ8LN", "Y5D1WT", "C6H9BG", "N2X7JR"]):
                        self._process_all_banners(content)
                    else:
                        self.insert_colored_text(content)
            self.output_text.see(tk.END)
            self.command_entry.focus_force()
            session_id1 = self.session_table.item(selected_item, 'values')[0]
            session_id_item = selected_item[0]
            name = self.session_names.get(session_id_item, session_id1)
            self.lbl_session_name.config(text="Beacon")
            self.lbl2_session_name.config(text=": ")
            parts = str(name).split("-")
            if len(parts) >= 3:
                name_display = "-".join(parts[:3]) 
            else:
                name_display = name
            self.lbl3_session_name.config(text=name_display)
            self.rename_session_button.pack(side=tk.LEFT, fill=tk.Y, pady=4, padx=3)
            session_data = None
            for k, v in self.sessions.items():
                if str(k) == str(session_id):
                    session_data = v
                    break
            show_exfiltration = False
            if session_data and len(session_data) > 4:
                exfiltration_profile = session_data[4]
                profile = str(exfiltration_profile).strip() if exfiltration_profile else ""
                show_exfiltration = profile in ["OneDrive", "Google Drive", "Dropbox"]
            self._toggle_exfiltration_menu(show_exfiltration)
            if session_id in self.session_terminal_mode:
                saved_mode = self.session_terminal_mode[session_id]
                self.selected_var.set(saved_mode)
                self.update_terminal_options_for_session(saved_mode)
            else:
                system_name = self.session_table.item(selected_item, "text").lower()
                if "linux" in system_name.lower():
                    default_mode = "Bash"
                else:
                    default_mode = "PowerShell"
                self.selected_var.set(default_mode)
                self.session_terminal_mode[session_id] = default_mode
                self.update_terminal_options_for_session(default_mode)
        else:
            self._toggle_exfiltration_menu(False)
    def _toggle_exfiltration_menu(self, show=False):
        self.show_exfiltration = show
