    def insert_colored_text(self, text):
        index = "end"
        patterns = {
            re.escape("[+]"): "yellow",
            re.escape("[-]"): "red",
            re.escape("[i]"): "blue",
            re.escape("[*]"): "green",
            re.escape("[!]"): "yellow",
            re.escape("-----BEGIN PUBLIC KEY-----"): "green",
            re.escape("-----END PUBLIC KEY-----"): "green"
        }
        yellow_keywords = [
            "WinDefend", "Kaspersky", "ESET", "CrowdStrike", "SentinelOne", "Sophos",
            "McAfee", "Avast", "Bitdefender", "Cylance", "Norton", "Webroot", "TrendMicro",
            "Symantec", "Malwarebytes", "CarbonBlack", "PaloAlto", "CortexXDR", "FireEye",
            "MicrosoftDefender", "Trellix", "DeepInstinct", "CheckPoint", "Harmony",
            "FortiEDR", "CiscoSecureEndpoint", "ElasticEDR",
            "Wireshark", "Fiddler", "TCPView", "NetMon", "EtherApe", "SmartSniff", "MicrosoftNetworkMonitor",
            "ida", "x64dbg", "ghidra", "pe-studio", "pestudio", "procmon", "procexp",
            "dnSpy", "OllyDbg", "radare",
            "VBoxService", "vboxmrxnp", "VMwareService", "vmtoolsd", "vmsrvc", "vboxtray",
            "vmware-authd", "vmacthlp", "vmwareuser", "vmwaretray", "virtualbox",
            "vmware-vmx", "vmx86", "VirtualBoxVM"
        ]
        for keyword in yellow_keywords:
            patterns[re.escape(keyword)] = "yellow"
        combined_pattern = "|".join(f"({p})" for p in patterns)
        for line in text.splitlines(keepends=True):  
            last_pos = 0
            for match in re.finditer(combined_pattern, line):
                start, end = match.start(), match.end()
                if start > last_pos:
                    self.output_text.insert(index, line[last_pos:start])
                matched_text = match.group(0)
                color = patterns[re.escape(matched_text)]
                self.output_text.insert(index, matched_text, color)
                last_pos = end
            if last_pos < len(line):
                self.output_text.insert(index, line[last_pos:])
