    def on_close(self):
        try:
            if messagebox.askokcancel("Quit", "Do you want to quit?"):
                self.shutdown_server()  
                self.cleanup_certificates_host_file()
                self.cleanup_certificates_phishing()
                self.clear_ssl_certs()
                self.on_closing()
        except:
            pass
    def shutdown_server(self):
        try:
            server_attrs = [
                'active_http_listeners', 'active_http_xor_listeners', 'active_http_aes_listeners',
                'active_https_listeners', 'active_https_aes_listeners', 'active_https_xor_listeners',
                'active_http_rc4_listeners', 'active_https_rc4_listeners','active_http_des_listeners',
                'active_http_chacha_listeners','active_http_rsa_listeners',
                'active_https_des_listeners', 'active_https_chacha_listeners', 'active_https_rsa_listeners'
            ]
            for attr_name in server_attrs:
                if hasattr(self, attr_name):
                    server_obj = getattr(self, attr_name)
                    if server_obj is None:
                        continue
                    if isinstance(server_obj, dict):
                        for instance in server_obj.values():
                            if instance and hasattr(instance, 'stop_server'):
                                try:
                                    instance.stop_server()
                                except:
                                    pass
                        setattr(self, attr_name, None)
                    elif hasattr(server_obj, 'stop_server'):
                        try:
                            server_obj.stop_server()
                        except:
                            pass
                        setattr(self, attr_name, None)
            if hasattr(self, 'main_application_window'):
                self.main_application_window.destroy()
        except:
            if hasattr(self, 'main_application_window'):
                self.main_application_window.quit()       
    def clear_logs(self):
        self.general_bear_banner_printed = False
        if not self.general_bear_banner_printed:
            self.update_output_text(f"A9F2KX", is_general=True)
            self.general_bear_banner_printed = True
        log_dirs = [
            os.path.join("Logs - Cert", "Beacons"),
            os.path.join("Logs - Cert", "General"),
        ]
        check_dirs = [
            os.path.join("Logs - Cert", "Beacons"),
        ]
        has_logs_to_delete = False
        for dir_path in check_dirs:
            if os.path.exists(dir_path):
                files = glob.glob(os.path.join(dir_path, "*.log"))
                if files:
                    has_logs_to_delete = True
                    break  
        for dir_path in log_dirs:
            if os.path.exists(dir_path):
                files = glob.glob(os.path.join(dir_path, "*.log"))
                for file in files:
                    try:
                        os.remove(file)
                    except Exception as e:
                        self.update_output_text(f"Error deleting {file}: {e}")
        self.current_view = 'session'
        self.show_output_text_general()
        if has_logs_to_delete:
            self.update_output_text(f"\n[!] All logs have been deleted successfully\n", is_general="double")
        else:
            self.update_output_text(f"\n[i] No log files found to delete...\n", is_general="double")
    def clear_ssl_certs(self):
        if not self.general_bear_banner_printed:
            self.update_output_text(f"A9F2KX", is_general=True)
            self.general_bear_banner_printed = True
        ssl_directory = os.path.join("Logs - Cert", "SSL-TLS")
        if not os.path.exists(ssl_directory):
            self.update_output_text("\n[!] SSL/TLS directory does not exist\n", is_general="double")
            return
        files = glob.glob(os.path.join(ssl_directory, "*.pem"))  
        if not files:
            self.update_output_text("\n[i] No SSL/TLS certificates found to delete...\n", is_general="double")
            return
        for file in files:
            try:
                os.remove(file)
            except Exception as e:
                self.update_output_text(f"[!] Failed to delete {file}: {e}\n", is_general="double")
        self.update_output_text("[!] SSL/TLS certificates have been deleted from logs/ssl...\n", is_general="double")
