    def obfuscate_batch(self, input_file, output_file):
        try:
            with open(input_file, 'rb') as f:
                content = f.read()
            encoded = base64.b64encode(content).decode('utf-8')
            lines = [encoded[i:i+76] for i in range(0, len(encoded), 76)]
            uid = self.random_id()
            b64_file = 'temp_' + uid + '.b64'
            decoded_file = 'decoded_' + uid + '.bat'
            bat = '@echo off' + chr(10) + 'setlocal EnableDelayedExpansion' + chr(10) + '(' + chr(10)
            for line in lines:
                bat += 'echo ' + line + chr(10)
            bat += ') > "%temp%\\' + b64_file + '"' + chr(10) + 'certutil -decode "%temp%\\' + b64_file + '" "%temp%\\' + decoded_file + '" >nul 2>&1' + chr(10) + 'if exist "%temp%\\' + decoded_file + '" (' + chr(10) + 'call "%temp%\\' + decoded_file + '"' + chr(10) + 'del "%temp%\\' + b64_file + '" >nul 2>&1' + chr(10) + 'del "%temp%\\' + decoded_file + '" >nul 2>&1' + chr(10) + ')' + chr(10) + 'endlocal'
            with open(output_file, 'w', encoding='utf-8') as f:
                f.write(bat)
            return True
        except Exception as e:
            self.log_message_Obfuscator(f"Batch obfuscation failed: {str(e)}", "error")
            return False
    def check_already_obfuscated(self, content, file_ext):
        patterns = {'.ps1': r'\$.*=\s*\[System\.Convert\]::FromBase64String', '.html': r'atob\([\'"]', '.vbs': r'Function.*Execute', '.js': r'eval\s*\(\s*atob', '.bat': r'certutil', '.py': r'zlib\.decompress'}
        pattern = patterns.get(file_ext, '')
        return bool(re.search(pattern, content, re.DOTALL)) if pattern else False
    def obfuscate_script(self):
        if not self.selected_file:
            self.log_message_Obfuscator("Please select a file first!", "error")
            return
        has_options = any([self.options['rename_variables'].get(), self.options['add_junk_code'].get(), self.options['encrypt_strings'].get(), self.options['multiple_layers'].get(), self.options['anti_debug'].get(), self.options['xor_encryption'].get()])
        if not has_options:
            self.log_message_Obfuscator("No options selected!.", "warning")
            return
        if not os.path.exists(self.selected_file):
            self.log_message_Obfuscator(f"File not found: {self.selected_file}", "error")
            return
        output_name = f"obfuscated_{self.base_name}"
        file_ext = os.path.splitext(self.selected_file)[1].lower()
        if not output_name.endswith(file_ext):
            output_name = output_name + file_ext
        self.log_message_Obfuscator("-" * 50, "info")
        self.log_message_Obfuscator("Starting obfuscation process...", "info")
        try:
            if file_ext == '.bat':
                success = self.obfuscate_batch(self.selected_file, output_name)
                if success:
                    self.log_message_Obfuscator("-" * 50, "info")
                    self.log_message_Obfuscator(f"File obfuscated successfully!", "success")
                    self.log_message_Obfuscator(f"Output: {output_name}", "success")
                return
            with open(self.selected_file, 'r', encoding='utf-8', errors='ignore') as f:
                content = f.read()
            if not content.strip():
                self.log_message_Obfuscator(f"File is empty!", "error")
                return
            if self.check_already_obfuscated(content, file_ext):
                self.log_message_Obfuscator("File appears to be already obfuscated!", "warning")
                response = messagebox.askyesno("Warning", "This file appears to be already obfuscated. Continue anyway?", parent=self.window_script_obfuscator)
                if not response:
                    return
            obfuscated_content = None
            if file_ext == '.ps1':
                self.log_message_Obfuscator("Obfuscating PowerShell script...", "info")
                obfuscated_content = self.obfuscate_powershell(content)
            elif file_ext == '.html':
                self.log_message_Obfuscator("Obfuscating HTML file...", "info")
                obfuscated_content = self.obfuscate_html(content)
            elif file_ext == '.vbs':
                self.log_message_Obfuscator("Obfuscating VBScript...", "info")
                obfuscated_content = self.obfuscate_vbs(content)
            elif file_ext == '.js':
                self.log_message_Obfuscator("Obfuscating JavaScript...", "info")
                obfuscated_content = self.obfuscate_javascript(content)
            elif file_ext == '.py':
                self.log_message_Obfuscator("Obfuscating Python script...", "info")
                obfuscated_content = self.obfuscate_python(content)
            else:
                self.log_message_Obfuscator(f"Unsupported file type: {file_ext}", "error")
                return
            if obfuscated_content and self.write_file(output_name, obfuscated_content):
                try:
                    file_size = os.path.getsize(output_name)
                    self.log_message_Obfuscator(f"File obfuscated successfully!", "success")
                    self.log_message_Obfuscator(f"Output: {output_name} ({file_size} bytes)", "success")
                    self.log_message_Obfuscator("-" * 50, "info")
                except:
                    self.log_message_Obfuscator(f"File obfuscated successfully!", "success")
                    self.log_message_Obfuscator(f"Output: {output_name}", "success")
                    self.log_message_Obfuscator("-" * 50, "info")
            else:
                self.log_message_Obfuscator("Failed to create output file!", "error")
        except Exception as e:
            self.log_message_Obfuscator(f"Error: {str(e)}", "error")
            self.log_message_Obfuscator("-" * 50, "info")
    def show_proxy_context_menu(self, event):
        row_id = self.proxy_table_proxy.identify_row(event.y)
        if row_id:
            self.proxy_table_proxy.selection_set(row_id)
            menu_window = tk.Toplevel(self.proxy_table_proxy.winfo_toplevel())
            menu_window.withdraw()
            menu_window.wm_overrideredirect(True)
            menu_window.configure(bg='#212121')
            border_frame = tk.Frame(menu_window, bg='#9A1105', padx=1, pady=1)
            border_frame.pack()
            inner_frame = tk.Frame(border_frame, bg='#212121')
            inner_frame.pack(fill='both', expand=True)
            def hide_menu():
                try:
                    menu_window.destroy()
                except:
                    pass
            def close_socket_action():
                hide_menu()
                self.stop_selected_proxy()
            label = tk.Label(
                inner_frame,
                text="  Close Socket  ",
                bg='#212121',
                fg='white',
                padx=20,
                pady=8,
                cursor='hand2',
                font=('Arial', 10)
            )
            label.pack(fill='x')
            def on_enter(e):
                label.configure(bg='#9A1105')
            def on_leave(e):
                label.configure(bg='#212121')
            def on_click(e):
                close_socket_action()
            label.bind('<Enter>', on_enter)
            label.bind('<Leave>', on_leave)
            label.bind('<Button-1>', on_click)
            menu_window.update_idletasks()
            width = menu_window.winfo_reqwidth()
            height = menu_window.winfo_reqheight()
            x = event.x_root
            y = event.y_root
            screen_width = menu_window.winfo_screenwidth()
            screen_height = menu_window.winfo_screenheight()
            if x + width > screen_width:
                x = screen_width - width - 10
            if y + height > screen_height:
                y = screen_height - height - 10
            menu_window.geometry(f"{width}x{height}+{x}+{y}")
            menu_window.deiconify()
            menu_window.lift()
            menu_window.focus_set()
            menu_window.transient(self.proxy_table_proxy.winfo_toplevel())
            menu_window.bind("<FocusOut>", lambda e: hide_menu())
            menu_window.bind("<Escape>", lambda e: hide_menu())
    def is_valid_ip_proxy(self, ip_address_proxy):
        pattern_proxy = re.compile(r"^(?:[0-9]{1,3}\.){3}[0-9]{1,3}$")
        return pattern_proxy.match(ip_address_proxy)
    def select_socks4_proxy(self):
        self.protocol_variable_proxy.set("SOCKS4")
        self.update_radio_images_proxy()
        self.on_protocol_select_proxy("SOCKS4")
    def select_socks4a_proxy(self):
        self.protocol_variable_proxy.set("SOCKS4a")
        self.update_radio_images_proxy()
        self.on_protocol_select_proxy("SOCKS4a")
    def select_socks5_proxy(self):
        self.protocol_variable_proxy.set("SOCKS5")
        self.update_radio_images_proxy()
        self.on_protocol_select_proxy("SOCKS5")
    def select_proxy_mode_proxy(self):
        self.mode_variable_proxy.set("PROXY")
        self.on_protocol_select_proxy(self.protocol_variable_proxy.get())
    def select_redirector_mode_proxy(self):
        self.mode_variable_proxy.set("REDIRECTOR")
        self.on_protocol_select_proxy(self.protocol_variable_proxy.get())
    def update_radio_images_proxy(self):
        current_protocol_proxy = self.protocol_variable_proxy.get()
        self.radio_socks4_proxy.config(image=self.radio_unselected_icon)
        self.radio_socks5_proxy.config(image=self.radio_unselected_icon)
        self.radio_socks4a_proxy.config(image=self.radio_unselected_icon)
        if current_protocol_proxy == "SOCKS4":
            self.radio_socks4_proxy.config(image=self.radio_selected_icon)
        elif current_protocol_proxy == "SOCKS5":
            self.radio_socks5_proxy.config(image=self.radio_selected_icon)
        elif current_protocol_proxy == "SOCKS4a":
            self.radio_socks4a_proxy.config(image=self.radio_selected_icon)
    def on_protocol_select_proxy(self, value_proxy):
        self.protocol_variable_proxy.set(value_proxy)
        self.update_radio_images_proxy()
        if self.mode_variable_proxy.get() == "PROXY":
            self.target_ip_label_proxy.config(fg="#515151")
            self.target_port_label_proxy.config(fg="#515151")
            self.target_ip_entry_proxy.config(bg="#2F2F2F",fg="#959595",state="readonly",insertbackground="#2F2F2F",selectforeground="#959595",selectbackground="#2F2F2F",readonlybackground="#2F2F2F")
            self.target_port_entry_proxy.config(bg="#2F2F2F",fg="#959595",state="readonly",insertbackground="#2F2F2F",selectforeground="#959595",selectbackground="#2F2F2F",readonlybackground="#2F2F2F")
            self.target_ip_entry_proxy.delete(0, tk.END)
            self.target_port_entry_proxy.delete(0, tk.END)
        else:
            self.target_ip_label_proxy.config(fg="#FFFFFF")
            self.target_port_label_proxy.config(fg="#FFFFFF")
            self.target_ip_entry_proxy.config(bg="#3E3E3E",fg="#FFFFFF",state="normal",selectbackground="#730f06",selectforeground="#FFFFFF",insertbackground="#730f06")
            self.target_port_entry_proxy.config(bg="#3E3E3E",fg="#FFFFFF",state="normal",selectbackground="#730f06",selectforeground="#FFFFFF",insertbackground="#730f06")
    def handle_socks4_protocol_proxy(self, client_socket_proxy, target_ip_proxy, target_port_proxy, proxy_id_proxy=None):
        try:
            header_proxy = client_socket_proxy.recv(8)
            if len(header_proxy) < 8:
                client_socket_proxy.close()
                return
            version_proxy, command_proxy = struct.unpack('!BB', header_proxy[:2])
            dst_port_proxy = struct.unpack('!H', header_proxy[2:4])[0]
            dst_ip_proxy = socket.inet_ntoa(header_proxy[4:8])
            if version_proxy != 4:
                error_response_proxy = struct.pack('!BBHI', 0, 0x5B, 0, 0)
                client_socket_proxy.sendall(error_response_proxy)
                client_socket_proxy.close()
                return
            if command_proxy != 1:
                error_response_proxy = struct.pack('!BBHI', 0, 0x5B, 0, 0)
                client_socket_proxy.sendall(error_response_proxy)
                client_socket_proxy.close()
                return
            userid_proxy = b''
            while True:
                byte_proxy = client_socket_proxy.recv(1)
                if not byte_proxy or byte_proxy == b'\x00':
                    break
                userid_proxy += byte_proxy
            user_str_proxy = userid_proxy.decode('utf-8', errors='ignore') or "anonymous"
            actual_target_ip_proxy = dst_ip_proxy
            is_socks4a_proxy = False
            if header_proxy[4:7] == b'\x00\x00\x00' and header_proxy[7] != 0:
                is_socks4a_proxy = True
                domain_proxy = b''
                MAX_DOMAIN_LEN = 255
                while len(domain_proxy) < MAX_DOMAIN_LEN:
                    byte_proxy = client_socket_proxy.recv(1)
                    if not byte_proxy or byte_proxy == b'\x00':
                        break
                    domain_proxy += byte_proxy
                if len(domain_proxy) >= MAX_DOMAIN_LEN:
                    client_socket_proxy.close()
                    return                    
                actual_target_ip_proxy = domain_proxy.decode('utf-8', errors='ignore')
            try:
                target_socket_proxy = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                target_socket_proxy.settimeout(30)
                if self.mode_variable_proxy.get() == "PROXY":
                    target_socket_proxy.connect((actual_target_ip_proxy, dst_port_proxy))
                else:
                    target_socket_proxy.connect((target_ip_proxy, target_port_proxy))
                response_proxy = struct.pack('!BBH4s', 0, 0x5A, dst_port_proxy, socket.inet_aton(target_socket_proxy.getpeername()[0]))
                client_socket_proxy.sendall(response_proxy)
                with self.connection_lock_proxy:
                    self.active_connections_proxy[client_socket_proxy] = {
                        "target_socket": target_socket_proxy,
                        "protocol": f"{'SOCKS4a' if is_socks4a_proxy else 'SOCKS4'}/TCP",
                        "address": str(client_socket_proxy.getpeername()),
                        "username": user_str_proxy,
                        "proxy_id": proxy_id_proxy
                    }
                threading.Thread(target=self.forward_data_proxy, args=(client_socket_proxy, target_socket_proxy, proxy_id_proxy), daemon=True).start()
                threading.Thread(target=self.forward_data_proxy, args=(target_socket_proxy, client_socket_proxy, proxy_id_proxy), daemon=True).start()
            except Exception as e_proxy:
                error_response_proxy = struct.pack('!BBHI', 0, 0x5B, 0, 0)
                client_socket_proxy.sendall(error_response_proxy)
                client_socket_proxy.close()
        except Exception as error_proxy:
            try:
                client_socket_proxy.close()
            except:
                pass   
    def handle_socks5_protocol_proxy(self, client_socket_proxy, target_ip_proxy, target_port_proxy, proxy_id_proxy=None):
        try:
            greeting_data_proxy = client_socket_proxy.recv(255)
            if len(greeting_data_proxy) < 2:
                client_socket_proxy.close()
                return
            version_proxy, num_methods_proxy = struct.unpack('!BB', greeting_data_proxy[:2])
            methods_proxy = greeting_data_proxy[2:2+num_methods_proxy] if len(greeting_data_proxy) >= 2+num_methods_proxy else b''
            if version_proxy != 5:
                client_socket_proxy.close()
                return
            methods_list_proxy = list(greeting_data_proxy[2:2+num_methods_proxy])
            if not self.handle_socks5_auth_proxy(client_socket_proxy, methods_list_proxy):
                client_socket_proxy.close()
                return
            request_data_proxy = client_socket_proxy.recv(255)
            if len(request_data_proxy) < 4:
                client_socket_proxy.close()
                return
            version_req_proxy, command_proxy, reserved_proxy, addr_type_proxy = struct.unpack('!BBBB', request_data_proxy[:4])
            if command_proxy == 1:
                self.handle_socks5_connect_proxy(client_socket_proxy, request_data_proxy, target_ip_proxy, target_port_proxy, proxy_id_proxy)
            elif command_proxy == 3:
                self.handle_socks5_udp_associate_proxy(client_socket_proxy, target_ip_proxy, target_port_proxy, proxy_id_proxy)
            else:
                error_response_proxy = struct.pack('!BBBBIH', 5, 7, 0, 1, 0, 0)
                client_socket_proxy.sendall(error_response_proxy)
                client_socket_proxy.close()
        except Exception as error_proxy:
            try:
                client_socket_proxy.close()
            except:
                pass
    def handle_socks5_connect_proxy(self, client_socket_proxy, request_data_proxy, target_ip_proxy, target_port_proxy, proxy_id_proxy=None):
        try:
            if len(request_data_proxy) < 4:
                client_socket_proxy.close()
                return
            addr_type_proxy = request_data_proxy[3]
            if addr_type_proxy == 1:  
                if len(request_data_proxy) < 10:
                    client_socket_proxy.close()
                    return
                dst_ip_proxy = socket.inet_ntoa(request_data_proxy[4:8])
                dst_port_proxy = struct.unpack('!H', request_data_proxy[8:10])[0]
                addr_type_for_connect = socket.AF_INET
            elif addr_type_proxy == 3:  
                if len(request_data_proxy) < 5:
                    client_socket_proxy.close()
                    return
                domain_len_proxy = request_data_proxy[4]
                required_len = 5 + domain_len_proxy + 2 
                if len(request_data_proxy) < required_len:
                    client_socket_proxy.close()
                    return
                domain_proxy = request_data_proxy[5:5+domain_len_proxy].decode('utf-8', errors='ignore')
                dst_port_proxy = struct.unpack('!H', request_data_proxy[5+domain_len_proxy:5+domain_len_proxy+2])[0]
                dst_ip_proxy = domain_proxy
                addr_type_for_connect = socket.AF_INET
            elif addr_type_proxy == 4:  
                if len(request_data_proxy) < 22:
                    client_socket_proxy.close()
                    return
                dst_ip_proxy = socket.inet_ntop(socket.AF_INET6, request_data_proxy[4:20])
                dst_port_proxy = struct.unpack('!H', request_data_proxy[20:22])[0]
                addr_type_for_connect = socket.AF_INET6
            else:
                client_socket_proxy.close()
                return
            try:
                if self.mode_variable_proxy.get() == "REDIRECTOR":
                    target_socket_proxy = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                    target_socket_proxy.settimeout(30)
                    target_socket_proxy.connect((target_ip_proxy, target_port_proxy))
                else:
                    if addr_type_proxy == 4: 
                        target_socket_proxy = socket.socket(socket.AF_INET6, socket.SOCK_STREAM)
                        target_socket_proxy.settimeout(30)
                        target_socket_proxy.connect((dst_ip_proxy, dst_port_proxy, 0, 0))
                    else:
                        target_socket_proxy = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                        target_socket_proxy.settimeout(30)
                        target_socket_proxy.connect((dst_ip_proxy, dst_port_proxy))
                bind_ip_proxy = target_socket_proxy.getpeername()[0]
                if ":" in bind_ip_proxy:
                    addr_bytes_proxy = socket.inet_pton(socket.AF_INET6, bind_ip_proxy)
                    atyp_proxy = 4
                else:
                    addr_bytes_proxy = socket.inet_aton(bind_ip_proxy)
                    atyp_proxy = 1
                response_proxy = struct.pack('!BBBB', 5, 0, 0, atyp_proxy) + addr_bytes_proxy + struct.pack('!H', dst_port_proxy)
                client_socket_proxy.sendall(response_proxy)
                with self.connection_lock_proxy:
                    self.active_connections_proxy[client_socket_proxy] = {
                        "target_socket": target_socket_proxy,
                        "protocol": "SOCKS5/TCP",
                        "address": str(client_socket_proxy.getpeername()),
                        "proxy_id": proxy_id_proxy
                    }
                threading.Thread(target=self.forward_data_proxy, args=(client_socket_proxy, target_socket_proxy, proxy_id_proxy), daemon=True).start()
                threading.Thread(target=self.forward_data_proxy, args=(target_socket_proxy, client_socket_proxy, proxy_id_proxy), daemon=True).start()
            except Exception as e_proxy:
                try:
                    client_socket_proxy.close()
                except:
                    pass
        except Exception as error_proxy:
            try:
                client_socket_proxy.close()
            except:
                pass
    def handle_socks5_udp_associate_proxy(self, client_socket_proxy, target_ip_proxy, target_port_proxy, proxy_id_proxy=None):
        try:
            udp_socket_proxy = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
            udp_socket_proxy.bind(('0.0.0.0', 0))
            udp_listen_ip_proxy, udp_listen_port_proxy = udp_socket_proxy.getsockname()
            bound_address_proxy = socket.inet_aton(target_ip_proxy)
            response_proxy = struct.pack('!BBBB', 5, 0, 0, 1) + bound_address_proxy + struct.pack('!H', udp_listen_port_proxy)
            client_socket_proxy.sendall(response_proxy)
            with self.connection_lock_proxy:
                self.active_connections_proxy[udp_socket_proxy] = {
                    "type": "UDP",
                    "protocol": "SOCKS5/UDP",
                    "address": f"{target_ip_proxy}:{target_port_proxy}",
                    "client_socket": client_socket_proxy,
                    "proxy_id": proxy_id_proxy
                }
            threading.Thread(
                target=self.relay_udp_data_proxy,
                args=(udp_socket_proxy, target_ip_proxy, target_port_proxy, client_socket_proxy, proxy_id_proxy),
                daemon=True
            ).start()
        except Exception as error_proxy:
            try:
                error_response_proxy = struct.pack('!BBBBIH', 5, 1, 0, 1, 0, 0)
                client_socket_proxy.sendall(error_response_proxy)
            except:
                pass
            try:
                client_socket_proxy.close()
            except:
                pass
    def handle_socks5_auth_proxy(self, client_socket_proxy, methods_proxy):
        MAX_USERNAME_LEN = 255
        MAX_PASSWORD_LEN = 255
        try:
            if 2 in methods_proxy and not self.socks5_no_auth_proxy:
                client_socket_proxy.sendall(struct.pack('!BB', 5, 2))
                auth_data_proxy = client_socket_proxy.recv(1024)
                if len(auth_data_proxy) < 5:
                    return False
                uname_len_proxy = auth_data_proxy[1]
                if uname_len_proxy > MAX_USERNAME_LEN or uname_len_proxy == 0:
                    client_socket_proxy.sendall(struct.pack('!BB', 1, 1))
                    return False
                if len(auth_data_proxy) < 2 + uname_len_proxy + 1:
                    return False
                uname_proxy = auth_data_proxy[2:2+uname_len_proxy].decode('utf-8', errors='ignore')
                passwd_len_proxy = auth_data_proxy[2+uname_len_proxy]
                if passwd_len_proxy > MAX_PASSWORD_LEN or passwd_len_proxy == 0:
                    client_socket_proxy.sendall(struct.pack('!BB', 1, 1))
                    return False
                if len(auth_data_proxy) < 3 + uname_len_proxy + passwd_len_proxy:
                    return False
                passwd_proxy = auth_data_proxy[3+uname_len_proxy:3+uname_len_proxy+passwd_len_proxy].decode('utf-8', errors='ignore')
                if uname_proxy == self.username_proxy and passwd_proxy == self.password_proxy:
                    client_socket_proxy.sendall(struct.pack('!BB', 1, 0))
                    return True
                else:
                    client_socket_proxy.sendall(struct.pack('!BB', 1, 1))
                    return False
            else:
                if 0 in methods_proxy:
                    client_socket_proxy.sendall(struct.pack('!BB', 5, 0))
                    return True
                else:
                    client_socket_proxy.sendall(struct.pack('!BB', 5, 0xFF))
                    return False
        except Exception as error_proxy:
            try:
                client_socket_proxy.sendall(struct.pack('!BB', 5, 0xFF))
            except:
                pass
            return False
    def relay_udp_data_proxy(self, udp_socket_proxy, target_ip_proxy, target_port_proxy, client_socket_proxy, proxy_id_proxy=None):
        try:
            target_socket_proxy = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
            target_socket_proxy.settimeout(30)
            while True:
                try:
                    if proxy_id_proxy and proxy_id_proxy not in self.active_proxies_proxy:
                        break
                    data_proxy, client_addr_proxy = udp_socket_proxy.recvfrom(4096)
                    if len(data_proxy) > 0:
                        if len(data_proxy) >= 4:
                            addr_proxy, port_proxy, payload_proxy = self.parse_socks5_udp_proxy(data_proxy)
                            target_socket_proxy.sendto(payload_proxy, (addr_proxy, port_proxy))
                            response_data_proxy, _ = target_socket_proxy.recvfrom(4096)
                            socks5_response_proxy = struct.pack('!HBB', 0, 0, 1)
                            socks5_response_proxy += socket.inet_aton(target_ip_proxy)
                            socks5_response_proxy += struct.pack('!H', target_port_proxy)
                            socks5_response_proxy += response_data_proxy
                            udp_socket_proxy.sendto(socks5_response_proxy, client_addr_proxy)
                except socket.timeout:
                    break
                except Exception as e_proxy:
                    break
        except Exception as error_proxy:
            pass
        finally:
            try:
                udp_socket_proxy.close()
            except:
                pass
            try:
                target_socket_proxy.close()
            except:
                pass
            with self.connection_lock_proxy:
                self.active_connections_proxy.pop(udp_socket_proxy, None)
    def parse_socks5_udp_proxy(self, data_proxy):
        if len(data_proxy) < 4:
            raise ValueError(f"UDP packet too short: expected at least 4 bytes, got {len(data_proxy)}")
        rsv_proxy, frag_proxy, atyp_proxy = struct.unpack('!HBB', data_proxy[:4])
        if frag_proxy != 0:
            raise ValueError(f"UDP fragmentation not supported: frag={frag_proxy}")
        if atyp_proxy == 1: 
            if len(data_proxy) < 10:
                raise ValueError(f"IPv4 UDP packet too short: expected at least 10 bytes, got {len(data_proxy)}")
            addr_proxy = socket.inet_ntoa(data_proxy[4:8])
            port_proxy = struct.unpack('!H', data_proxy[8:10])[0]
            payload_proxy = data_proxy[10:]
        elif atyp_proxy == 3: 
            if len(data_proxy) < 5:
                raise ValueError(f"Domain UDP packet too short: expected at least 5 bytes, got {len(data_proxy)}")
            length_proxy = data_proxy[4]
            required_len = 5 + length_proxy + 2
            if len(data_proxy) < required_len:
                raise ValueError(f"Domain UDP packet incomplete: expected {required_len} bytes, got {len(data_proxy)}")
            addr_proxy = data_proxy[5:5+length_proxy].decode('utf-8', errors='ignore')
            port_proxy = struct.unpack('!H', data_proxy[5+length_proxy:7+length_proxy])[0]
            payload_proxy = data_proxy[7+length_proxy:]
        elif atyp_proxy == 4:  
            if len(data_proxy) < 22:
                raise ValueError(f"IPv6 UDP packet too short: expected at least 22 bytes, got {len(data_proxy)}")
            addr_proxy = socket.inet_ntop(socket.AF_INET6, data_proxy[4:20])
            port_proxy = struct.unpack('!H', data_proxy[20:22])[0]
            payload_proxy = data_proxy[22:]
        else:
            raise ValueError(f"Unknown address type in UDP packet: {atyp_proxy}")
        return addr_proxy, port_proxy, payload_proxy
    def forward_data_proxy(self, source_socket_proxy, destination_socket_proxy, proxy_id_proxy=None):
        try:
            while True:
                ready_proxy, _, _ = select.select([source_socket_proxy], [], [], 1.0)
                if ready_proxy:
                    data_received_proxy = source_socket_proxy.recv(4096)
                    if not data_received_proxy:
                        break
                    try:
                        destination_socket_proxy.sendall(data_received_proxy)
                    except (BrokenPipeError, ConnectionResetError):
                        break
                else:
                    try:
                        source_socket_proxy.recv(1, socket.MSG_PEEK | socket.MSG_DONTWAIT)
                    except (BlockingIOError, socket.error):
                        pass
                    except (ConnectionResetError, BrokenPipeError):
                        break
                    except:
                        break
                if proxy_id_proxy and proxy_id_proxy not in self.active_proxies_proxy:
                    break
        except (OSError, ConnectionResetError, BrokenPipeError):
            pass
        except Exception as error_proxy:
            pass
        finally:
            try:
                source_socket_proxy.shutdown(socket.SHUT_RDWR)
            except:
                pass
            try:
                source_socket_proxy.close()
            except:
                pass
            try:
                destination_socket_proxy.shutdown(socket.SHUT_RDWR)
            except:
                pass
            try:
                destination_socket_proxy.close()
            except:
                pass
            with self.connection_lock_proxy:
                self.active_connections_proxy.pop(source_socket_proxy, None)
                self.active_connections_proxy.pop(destination_socket_proxy, None)
    def update_proxy_table_proxy(self):
        if not hasattr(self, 'proxy_table_proxy') or not self.proxy_table_proxy:
            return
        if not hasattr(self, 'window_listener') or not self.window_listener:
            return
        if not self.window_listener.winfo_exists():
            return
        for item_proxy in self.proxy_table_proxy.get_children():
            self.proxy_table_proxy.delete(item_proxy)
        with self.proxy_lock_proxy:
            for proxy_id_proxy, proxy_info_proxy in self.active_proxies_proxy.items():
                address_proxy = proxy_info_proxy.get("address", "Unknown")
                protocol_proxy = proxy_info_proxy.get("protocol", "Unknown")
                self.proxy_table_proxy.insert("", "end", iid=proxy_id_proxy, values=(address_proxy, protocol_proxy))
    def stop_selected_proxy(self):
        selected_items_proxy = self.proxy_table_proxy.selection()
        if not selected_items_proxy:
            return
        proxy_id_proxy = selected_items_proxy[0]
        def stop_proxy_task_proxy():
            with self.proxy_lock_proxy:
                if proxy_id_proxy not in self.active_proxies_proxy:
                    return 
                proxy_info_proxy = self.active_proxies_proxy[proxy_id_proxy]
                server_socket_proxy = proxy_info_proxy.get("server_socket")
                listen_port_proxy = proxy_info_proxy.get("port")
                self.active_proxies_proxy.pop(proxy_id_proxy, None)
                if server_socket_proxy:
                    try:
                        wake_socket_proxy = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                        wake_socket_proxy.settimeout(1)
                        wake_socket_proxy.connect(('127.0.0.1', listen_port_proxy))
                        wake_socket_proxy.close()
                    except:
                        pass
                    try:
                        server_socket_proxy.shutdown(socket.SHUT_RDWR)
                    except:
                        pass
                    try:
                        server_socket_proxy.close()
                    except:
                        pass
            with self.connection_lock_proxy:
                connections_to_close_proxy = []
                sockets_info = [] 
                for sock_proxy, conn_info_proxy in list(self.active_connections_proxy.items()):
                    if conn_info_proxy.get("proxy_id") == proxy_id_proxy:
                        connections_to_close_proxy.append(sock_proxy)
                        sockets_info.append((sock_proxy, conn_info_proxy))
                        target_sock = conn_info_proxy.get("target_socket")
                        if target_sock and target_sock not in connections_to_close_proxy:
                            connections_to_close_proxy.append(target_sock)
                for sock_proxy in connections_to_close_proxy:
                    try:
                        sock_proxy.shutdown(socket.SHUT_RDWR)
                    except:
                        pass
                    try:
                        sock_proxy.close()
                    except:
                        pass
                for sock_proxy, conn_info_proxy in sockets_info:
                    self.active_connections_proxy.pop(sock_proxy, None)
                    target_sock = conn_info_proxy.get("target_socket")
                    if target_sock:
                        self.active_connections_proxy.pop(target_sock, None)
            self.window_listener.after(0, self.update_proxy_table_proxy)
        threading.Thread(target=stop_proxy_task_proxy, daemon=True).start()
    def show_socks5_auth_dialog_proxy(self):
        auth_window_proxy = tk.Toplevel(self.window_listener)
        auth_window_proxy.transient(self.window_listener)
        auth_window_proxy.title("SOCKS5 Authentication")
        auth_window_proxy.geometry("300x170")
        auth_window_proxy.configure(bg="#0f1110")
        auth_window_proxy.resizable(False, False)
        no_auth_var_proxy = BooleanVar(value=False)
        def on_no_auth_change_proxy(event_proxy=None):
            no_auth_var_proxy.set(not no_auth_var_proxy.get())
            if no_auth_var_proxy.get():
                username_label_proxy.config(fg="#515151")
                password_label_proxy.config(fg="#515151")
                username_entry_proxy.configure(bg="#2F2F2F", fg="#959595", insertbackground="#2F2F2F",selectforeground="#959595", selectbackground="#2F2F2F",readonlybackground='#2F2F2F',highlightcolor="#0f1110",state="readonly")
                password_entry_proxy.configure(bg="#2F2F2F", fg="#959595", insertbackground="#2F2F2F",selectforeground="#959595", selectbackground="#2F2F2F",readonlybackground='#2F2F2F',highlightcolor="#0f1110",state="readonly")
                no_auth_check_proxy.configure(image=self.checkbox_checked_icon)
            else:
                username_label_proxy.config(fg="#FFFFFF")
                password_label_proxy.config(fg="#FFFFFF")
                username_entry_proxy.configure(bg="#3E3E3E",fg="#FFFFFF",state="normal",selectbackground="#730f06",selectforeground="#FFFFFF",insertbackground="#730f06",highlightcolor="#FFFFFF")
                password_entry_proxy.configure(bg="#3E3E3E",fg="#FFFFFF",state="normal",selectbackground="#730f06",selectforeground="#FFFFFF",insertbackground="#730f06",highlightcolor="#FFFFFF")
                no_auth_check_proxy.configure(image=self.checkbox_unchecked_icon)
        username_frame_proxy = tk.Frame(auth_window_proxy, bg="#0f1110")
        username_frame_proxy.pack(pady=10)
        username_label_proxy = tk.Label(username_frame_proxy, text="Username:", bg="#0f1110", fg="#FFFFFF")
        username_label_proxy.pack(side=tk.LEFT, padx=5)
        username_entry_proxy = tk.Entry(username_frame_proxy, width=20,bg="#3E3E3E",fg="#FFFFFF",state="normal",selectbackground="#730f06",selectforeground="#FFFFFF",insertbackground="#730f06",highlightcolor="#FFFFFF")
        username_entry_proxy.pack(side=tk.LEFT, padx=1)
        self.create_context_menu(username_entry_proxy)
        password_frame_proxy = tk.Frame(auth_window_proxy, bg="#0f1110")
        password_frame_proxy.pack(pady=5)
        password_label_proxy = tk.Label(password_frame_proxy, text="Password:", bg="#0f1110", fg="#FFFFFF")
        password_label_proxy.pack(side=tk.LEFT, padx=5)
        password_entry_proxy = tk.Entry(password_frame_proxy, width=20, bg="#3E3E3E", fg="#FFFFFF", show="*", insertbackground="#730f06")
        password_entry_proxy.pack(side=tk.LEFT, padx=(6,0))
        self.create_context_menu(password_entry_proxy)
        frame_no_auth_check_proxy = tk.Frame(auth_window_proxy, bg="#0f1110")
        frame_no_auth_check_proxy.pack(pady=5)
        no_auth_check_proxy = tk.Label(frame_no_auth_check_proxy, image=self.checkbox_unchecked_icon, bg="#0f1110", cursor="hand2")
        no_auth_check_proxy.pack(side=tk.LEFT, padx=1)
        no_auth_check_text_proxy = tk.Label(frame_no_auth_check_proxy, text="No Auth (Allow anonymous connections)", bg="#0f1110", fg="#FFFFFF")
        no_auth_check_text_proxy.pack(side=tk.LEFT, padx=1)
        no_auth_check_proxy.bind("<Button-1>", on_no_auth_change_proxy)
        no_auth_check_text_proxy.bind("<Button-1>", on_no_auth_change_proxy)
        def save_auth_proxy():
            if not no_auth_var_proxy.get():
                username = username_entry_proxy.get().strip()
                password = password_entry_proxy.get().strip()
                if not username or not password:
                    messagebox.showwarning(
                        "Warning",
                        "Please enter username and password or enable No Auth",
                        parent=auth_window_proxy
                    )
                    return 
                self.username_proxy = username
                self.password_proxy = password
                self.socks5_no_auth_proxy = False
            else:
                self.socks5_no_auth_proxy = True
            auth_window_proxy.destroy()
            self.start_proxy_server_after_auth_proxy()        
        button_frame_proxy = tk.Frame(auth_window_proxy, bg="#0f1110")
        button_frame_proxy.pack(pady=15)
        tk.Button(button_frame_proxy, text="OK", command=save_auth_proxy, bg="#730f06", fg="#FFFFFF", activebackground="#9A1105", activeforeground="#FFFFFF", width=12).pack(side=tk.LEFT, padx=5)
    def start_proxy_server_after_auth_proxy(self):
        target_ip_value_proxy = self.target_ip_entry_proxy.get()
        target_port_value_proxy = self.target_port_entry_proxy.get()
        proxy_listen_ip_proxy = self.proxy_host_entry_proxy.get()
        proxy_listen_port_proxy = self.proxy_port_entry_proxy.get()
        selected_protocol_proxy = self.protocol_variable_proxy.get()
        if not proxy_listen_port_proxy.isdigit():
            messagebox.showwarning("Warning", "Please enter a valid Proxy Port number", parent=self.window_listener)
            return
        proxy_listen_port_int_proxy = int(proxy_listen_port_proxy)
        if not (0 < proxy_listen_port_int_proxy < 65536):
            messagebox.showwarning("Warning", "Proxy Port must be between 1 and 65535", parent=self.window_listener)
            return
        if self.mode_variable_proxy.get() == "REDIRECTOR":
            if not target_ip_value_proxy or not target_port_value_proxy:
                messagebox.showwarning("Warning", "Target IP and Port cannot be empty in REDIRECTOR mode!", parent=self.window_listener)
                return
            if not self.is_valid_ip_proxy(target_ip_value_proxy):
                messagebox.showwarning("Warning", "Please enter a valid Target IP address", parent=self.window_listener)
                return
            if not target_port_value_proxy.isdigit():
                messagebox.showwarning("Warning", "Please enter a valid Target Port number", parent=self.window_listener)
                return
            target_port_int_proxy = int(target_port_value_proxy)
            if not (0 < target_port_int_proxy < 65536):
                messagebox.showwarning("Warning", "Target Port must be between 1 and 65535", parent=self.window_listener)
                return
        else:
            target_ip_value_proxy = "0.0.0.0"  
            target_port_int_proxy = 0 
        proxy_address_proxy = f"{proxy_listen_ip_proxy}:{proxy_listen_port_proxy}"
        self.proxy_counter_proxy += 1
        proxy_id_proxy = f"proxy_{self.proxy_counter_proxy}"
        threading.Thread(
            target=self.run_proxy_server_proxy,
            args=(proxy_listen_port_int_proxy, target_ip_value_proxy, target_port_int_proxy, selected_protocol_proxy, proxy_address_proxy, proxy_id_proxy),
            daemon=True
        ).start()
    def start_proxy_server_proxy(self):
        target_ip_value_proxy = self.target_ip_entry_proxy.get()
        target_port_value_proxy = self.target_port_entry_proxy.get()
        proxy_listen_ip_proxy = self.proxy_host_entry_proxy.get()
        proxy_listen_port_proxy = self.proxy_port_entry_proxy.get()
        selected_protocol_proxy = self.protocol_variable_proxy.get()
        ip, port = self.validate_ip_port(self.proxy_host_entry_proxy.get(), self.proxy_port_entry_proxy.get(), self.window_listener)
        if ip is None:
            return  
        if self.mode_variable_proxy.get() == "REDIRECTOR":
            if not target_ip_value_proxy or not target_port_value_proxy:
                messagebox.showwarning("Warning", "Target IP and Port cannot be empty in REDIRECTOR mode!", parent=self.window_listener)
                return
            if not self.is_valid_ip_proxy(target_ip_value_proxy):
                messagebox.showwarning("Warning", "Please enter a valid Target IP address", parent=self.window_listener)
                return
            if not target_port_value_proxy.isdigit():
                messagebox.showwarning("Warning", "Please enter a valid Target Port number", parent=self.window_listener)
                return
            target_port_int_proxy = int(target_port_value_proxy)
            if not (0 < target_port_int_proxy < 65536):
                messagebox.showwarning("Warning", "Target Port must be between 1 and 65535", parent=self.window_listener)
                return
        else:
            target_ip_value_proxy = "0.0.0.0" 
            target_port_int_proxy = 0          
        if not proxy_listen_port_proxy.isdigit():
            messagebox.showwarning("Warning", "Please enter a valid Proxy Port number", parent=self.window_listener)
            return
        proxy_listen_port_int_proxy = int(proxy_listen_port_proxy)
        if not (0 < proxy_listen_port_int_proxy < 65536):
            messagebox.showwarning("Warning", "Proxy Port must be between 1 and 65535", parent=self.window_listener)
            return
        proxy_address_proxy = f"{proxy_listen_ip_proxy}:{proxy_listen_port_proxy}"
        with self.proxy_lock_proxy:
            for proxy_info_proxy in self.active_proxies_proxy.values():
                if proxy_info_proxy.get("address") == proxy_address_proxy:
                    messagebox.showwarning("Warning", f"A proxy on {proxy_address_proxy} is already running!", parent=self.window_listener)
                    return
        if selected_protocol_proxy == "SOCKS5":
            self.show_socks5_auth_dialog_proxy()
            return
        self.proxy_counter_proxy += 1
        proxy_id_proxy = f"proxy_{self.proxy_counter_proxy}"
        threading.Thread(
            target=self.run_proxy_server_proxy,
            args=(proxy_listen_port_int_proxy, target_ip_value_proxy, target_port_int_proxy, selected_protocol_proxy, proxy_address_proxy, proxy_id_proxy),
            daemon=True
        ).start()
    def safe_update_proxy_table(self):
        try:
            if hasattr(self, 'window_listener') and self.window_listener:
                if self.window_listener.winfo_exists():
                    self.window_listener.after(0, self.update_proxy_table_proxy)
        except:
            pass
    def run_proxy_server_proxy(self, listen_port_proxy, target_ip_proxy, target_port_proxy, protocol_type_proxy, proxy_address_proxy, proxy_id_proxy):
        server_socket_proxy = None
        try:
            server_socket_proxy = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            server_socket_proxy.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            server_socket_proxy.bind(('', listen_port_proxy))
            server_socket_proxy.listen(10)
            server_socket_proxy.settimeout(1.0)  
            with self.proxy_lock_proxy:
                self.active_proxies_proxy[proxy_id_proxy] = {
                    "server_socket": server_socket_proxy,
                    "address": proxy_address_proxy,
                    "protocol": protocol_type_proxy,
                    "port": listen_port_proxy
                }
            self.safe_update_proxy_table()
            while True:
                try:
                    client_socket_proxy, client_address_proxy = server_socket_proxy.accept()
                    if protocol_type_proxy == "SOCKS4":
                        client_thread_proxy = threading.Thread(
                            target=self.handle_socks4_protocol_proxy,
                            args=(client_socket_proxy, target_ip_proxy, target_port_proxy, proxy_id_proxy),
                            daemon=True
                        )
                        client_thread_proxy.start()
                    elif protocol_type_proxy == "SOCKS4a":
                        client_thread_proxy = threading.Thread(
                            target=self.handle_socks4_protocol_proxy,
                            args=(client_socket_proxy, target_ip_proxy, target_port_proxy, proxy_id_proxy),
                            daemon=True
                        )
                        client_thread_proxy.start()
                    elif protocol_type_proxy == "SOCKS5":
                        client_thread_proxy = threading.Thread(
                            target=self.handle_socks5_protocol_proxy,
                            args=(client_socket_proxy, target_ip_proxy, target_port_proxy, proxy_id_proxy),
                            daemon=True
                        )
                        client_thread_proxy.start()
                except socket.timeout:
                    with self.proxy_lock_proxy:
                        if proxy_id_proxy not in self.active_proxies_proxy:
                            break
                    continue
                except OSError:
                    break
                except Exception as error_proxy:
                    continue
        except Exception as error_proxy:
            pass
        finally:
            with self.proxy_lock_proxy:
                self.active_proxies_proxy.pop(proxy_id_proxy, None)
            with self.connection_lock_proxy:
                connections_to_remove_proxy = []
                for sock_proxy, conn_info_proxy in list(self.active_connections_proxy.items()):
                    if conn_info_proxy.get("proxy_id") == proxy_id_proxy:
                        try:
                            sock_proxy.close()
                            connections_to_remove_proxy.append(sock_proxy)
                        except:
                            pass
                for sock_proxy in connections_to_remove_proxy:
                    self.active_connections_proxy.pop(sock_proxy, None)
            self.safe_update_proxy_table()
