    def validate_telegram_inputs(self, api_id, api_hash, phone_number, listener_name, bot_username):
        if not api_id:
            return "API ID cannot be empty"
        try:
            api_id_int = int(api_id)
            if api_id_int <= 0:
                return "API ID must be a positive number"
        except ValueError:
            return "API ID must be a valid number"
        if not api_hash:
            return "API Hash cannot be empty"
        if len(api_hash) < 32:
            return "API Hash must be at least 32 characters"
        if not phone_number:
            return "Phone number cannot be empty"
        phone_number = phone_number.strip()
        if not phone_number.startswith('+'):
            return "Phone number must start with '+' (+1234567890)"
        if not phone_number[1:].isdigit():
            return "Phone number must contain only digits after '+'"
        if not listener_name:
            return "Listener Name cannot be empty"
        listener_name = listener_name.strip()
        if len(listener_name) < 2:
            return "Listener Name must be at least 2 characters"
        if len(listener_name) > 50:
            return "Listener Name cannot exceed 50 characters"
        if not listener_name.replace(" ", "").isalnum():
            return "Listener Name can only contain letters, numbers, and spaces"
        if not bot_username:
            return "Bot username cannot be empty"
        bot_username = bot_username.strip()
        if not bot_username.startswith('@'):
            return "Bot username must start with '@' (@example_bot)"
        if ' ' in bot_username:
            return "Bot username cannot contain spaces"
        if len(bot_username) < 5:
            return "Bot username is too short"
        if not (bot_username.endswith('bot') or bot_username.endswith('_bot')):
            return "Bot username should end with 'bot' or '_bot'"
        return None
