            encrypted_append_output = xor_encrypt_decrypt_string(self.append_output, self.xor_encryption_key,self.use_urlsafe_base64_encoding)
            get_client_headers_text = '\n'.join(f"{k}: {v}" for k, v in sorted(self.get_client_headers.items()))
            post_client_headers_text = '\n'.join(f"{k}: {v}" for k, v in sorted(self.post_client_headers.items()))
            encrypted_get_client_headers = xor_encrypt_decrypt_string(get_client_headers_text, self.xor_encryption_key,self.use_urlsafe_base64_encoding)
