        self.rc4_key = rc4_cipher_instance
        self.reconnect_delay_entry = reconnect_delay_entry
        self.reconnect_timeout_entry = reconnect_timeout_entry
        self.Sleep = Sleep / 1000 
        self.listener_uuid = listener_uuid
        self.html_content = html_content
        self.get_server_headers = get_server_headers or {}
        self.post_server_headers = post_server_headers or {}
        self.prepend_output=prepend_output
        self.append_output=append_output
        self.user_agent = user_agent
        self.uris = uris
        self.session_limiting_enable = session_limiting_enable
        self.get_client_headers = get_client_headers
        self.post_client_headers = post_client_headers
        self.max_sessions_limit = max_total_sessions
        self.total_accepted_sessions = 0
