                if token != self.listener_uuid:
                    if not self.public_doh_servers:
                        return self.html_content, 200, {"Content-Type": "text/html"}
                    server = random.choice(self.public_doh_servers)
                    headers = {
                        "Content-Type": "application/dns-message",
                        "Accept": "application/dns-message",
                    }
