                    for part in to_send_now:
                        if len(part.encode('utf-8')) > self.max_txt_size:
                            continue
                        answers.append(self.build_rr(self.build_txt_rdata(part)))
                    sent_this_time = len(to_send_now)
                    sess["sent_parts_count"] += sent_this_time
